INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('486bf0dd-671e-45ca-82a1-b65001d0d67f', '29c220d8-81d9-4bd6-88aa-326fd74957a3', 0, 'The specialist reports the appropriate initial or subsequent hospital inpatient E/M code (rather than a consultation code) reflecting the level of service actually provided, since payers not recognizing consultation codes require using the standard hospital E/M code set instead');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2caaf648-e30d-4bcf-b97a-51e318d3475b', '29c220d8-81d9-4bd6-88aa-326fd74957a3', 1, 'The specialist simply does not bill anything for the encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('588e80d4-5555-40a1-b56b-1bebe9442443', '29c220d8-81d9-4bd6-88aa-326fd74957a3', 2, 'The specialist must always bill using an office visit E/M code regardless of the inpatient setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d848a42-455f-4470-aa29-f0c42d520fdc', '29c220d8-81d9-4bd6-88aa-326fd74957a3', 3, 'Consultation codes must still be used regardless of payer policy, with the claim expected to be denied');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bfd8097-2ad4-45d0-b377-2aaedb239502', '80ef2365-7f06-4d11-9b7d-4c24de368ffb', 0, 'These three elements (request for opinion, reason for request, report back to requester) remain useful documentation-quality concepts reflecting genuine specialist-to-referring-physician communication, even when the specific consultation CODE isn''t used due to payer policy — the underlying clinical communication is still good practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b182a20b-9772-4f57-af03-edb66807a1c5', '80ef2365-7f06-4d11-9b7d-4c24de368ffb', 1, 'These three elements are entirely obsolete concepts with zero continued relevance to any documentation practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7b6edc9-8de8-406a-962a-da37a674f989', '80ef2365-7f06-4d11-9b7d-4c24de368ffb', 2, 'The three elements apply only when consultation codes are actually billed, with no relevance to hospital E/M documentation generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd3c3e92-53f3-4c84-b3d3-b8a2f02d2e8e', '80ef2365-7f06-4d11-9b7d-4c24de368ffb', 3, 'Only the ''report'' element matters; request and reason are irrelevant to any encounter type');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b024ec8-d24b-4f5c-af6d-58633c1706a6', '200533b8-5a78-4d5c-9c36-4c555510fd98', 0, 'Critical care codes are based on cumulative time spent by the physician/QHP personally managing the critically ill patient (with specific time thresholds for the base code and add-on codes for additional time), reflecting a distinct time-counting and complexity structure from standard office/outpatient or hospital E/M codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd2b946c-3e6e-4d52-95c6-f15bc567fa87', '200533b8-5a78-4d5c-9c36-4c555510fd98', 1, 'Critical care is coded using the same time thresholds and code structure as standard office/outpatient E/M visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fdab72d0-348d-46f4-9c84-6c9f4c0e1ba7', '200533b8-5a78-4d5c-9c36-4c555510fd98', 2, 'Critical care codes are based solely on the patient''s ICU bed assignment, regardless of physician time/complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6484bdda-b865-4739-a623-d8bb3e8a607a', '200533b8-5a78-4d5c-9c36-4c555510fd98', 3, 'Critical care time may only be counted if the physician is physically at the bedside the entire time, with no allowance for other unit-based activities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f46ecab2-2bdd-4acd-9164-5708a89cb1e4', '5ec81b68-a862-4019-bd0f-60b7830d54fd', 0, 'Only time spent physically touching the patient counts toward critical care time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8098e4a4-9ef8-4bed-b85e-9b36f2727bee', '5ec81b68-a862-4019-bd0f-60b7830d54fd', 1, 'Time spent by the physician engaged in patient care activities on the unit/floor directly related to that specific critically ill patient (bedside time, reviewing test results, discussing care with other staff, documenting) generally counts, even when not literally at the bedside every minute, as long as the physician is immediately available and not simultaneously providing services to another patient');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ed8a17d-3a15-4eb5-9312-e9a95acca579', '5ec81b68-a862-4019-bd0f-60b7830d54fd', 2, 'Time spent on any hospital administrative task, regardless of relation to the specific patient, counts toward critical care time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('717ecee8-c485-4c50-850c-bd0fc41a40c7', '5ec81b68-a862-4019-bd0f-60b7830d54fd', 3, 'Critical care time counting excludes any time spent reviewing laboratory or imaging results');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5fd04f8-b0cc-47da-8a62-40af7c8f79de', 'bd3b03aa-5cde-471f-9c7f-25ce76b48d18', 0, 'Each encounter is coded on its own merits — critical care time for the critically ill patient (via the critical care code family) and the appropriate separate E/M code for the other, unrelated patient — since these are two entirely separate patients with no bearing on each other''s coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e10abd0-52a8-42f4-ace7-32fd382cd1a0', 'bd3b03aa-5cde-471f-9c7f-25ce76b48d18', 1, 'Only one of the two encounters may be billed on the same date by the same physician, regardless of which two distinct patients were involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4712cee8-0e56-463a-b9d4-77d65a2faa21', 'bd3b03aa-5cde-471f-9c7f-25ce76b48d18', 2, 'Critical care time must be reduced by however much time was spent on the other unrelated patient encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e290eb3f-99df-452c-8b9f-8edf44beb9f5', 'bd3b03aa-5cde-471f-9c7f-25ce76b48d18', 3, 'Both patients must be billed using the same E/M code regardless of their differing acuity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a76b059-7185-4992-a2b0-4cc0bb13817d', 'a24d8ea9-dd88-404b-a145-8e01b6c6341d', 0, 'A specific add-on code exists for additional critical care time increments beyond the base code''s threshold, reported for each additional qualifying time increment, distinct from the general prolonged E/M services add-on codes discussed for office/outpatient visits in Paper 1');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d4280a3-f514-433f-8f29-7cb38adf6b93', 'a24d8ea9-dd88-404b-a145-8e01b6c6341d', 1, 'No additional code exists for critical care time beyond the base threshold; all additional time is unbilled');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da3bb61f-0a0a-4535-a577-a4ab1529fbc7', 'a24d8ea9-dd88-404b-a145-8e01b6c6341d', 2, 'The same prolonged services add-on code used for office/outpatient E/M visits is used for additional critical care time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8085925a-0d54-4a9a-8347-cd58eed9d160', 'a24d8ea9-dd88-404b-a145-8e01b6c6341d', 3, 'Additional critical care time is billed by simply reporting the base critical care code a second time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88137f8e-0231-4248-9d8d-868408da1fc2', '607a7381-85eb-4a0f-afbc-e964b6cc3768', 0, 'CPT includes distinct code families specifically for neonatal and pediatric critical care (often structured differently from the adult critical care time-based codes, e.g., per-day codes for certain age/weight categories), reflecting the specialized nature of this care rather than simply applying adult critical care time thresholds');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0a8cc38-ca03-4306-9233-54c392399e50', '607a7381-85eb-4a0f-afbc-e964b6cc3768', 1, 'Neonatal/pediatric critical care is coded identically to adult critical care using the same time-based codes and thresholds');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab3816c4-0bf6-467c-82fb-24595280aeea', '607a7381-85eb-4a0f-afbc-e964b6cc3768', 2, 'Pediatric critical care has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ad67b3f-a295-4ce9-b9ee-467d8db479ad', '607a7381-85eb-4a0f-afbc-e964b6cc3768', 3, 'Neonatal critical care codes apply only to full-term infants, never premature infants');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3df7d73-d1fb-4d0b-98a5-e95e3c229fa9', '94f703e8-4e39-4718-a0f2-231ded0ef5fb', 0, 'Critical care codes may be reported by the ED physician for the critical care time/services they personally provided in the ED, regardless of the fact that the patient is later admitted to the ICU under a different physician''s care, since critical care coding is based on the actual service provided by the reporting physician, not which unit the patient is ultimately admitted to');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e367a8a5-eb57-4f45-ad4b-68fdf61aff7c', '94f703e8-4e39-4718-a0f2-231ded0ef5fb', 1, 'Only ICU physicians, never ED physicians, may ever report critical care codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4496a123-e250-470a-9ab3-3a294a7e7907', '94f703e8-4e39-4718-a0f2-231ded0ef5fb', 2, 'Critical care services provided in the ED are always bundled into a standard ED E/M visit code with no separate critical care reporting possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15de96cb-8c60-4c94-8980-19c15b45e49f', '94f703e8-4e39-4718-a0f2-231ded0ef5fb', 3, 'The ED physician must transfer all critical care time credit to the admitting ICU physician, reporting nothing themselves');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a206a27-8bef-4f7e-8481-9c61cb7b7ce5', '982c1d95-9621-48cf-90b1-6a9e43eb2c79', 0, 'The total critical care time provided by physicians of the same specialty/group during that calendar date is generally combined/summed and reported once (typically under one billing physician, per group-practice reporting conventions), rather than each physician separately billing their own portion as if unrelated to the other physician''s time that same day');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4fdaf01-0ce2-485e-8e1c-a738aad0bc7a', '982c1d95-9621-48cf-90b1-6a9e43eb2c79', 1, 'Each physician bills their own separate critical care code completely independently with no time-combination consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8d3f038-2e28-4376-a49c-60f49092492b', '982c1d95-9621-48cf-90b1-6a9e43eb2c79', 2, 'Same-specialty/group critical care time can never be combined under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c1e5013-0373-46ca-a8fa-361e70c014a4', '982c1d95-9621-48cf-90b1-6a9e43eb2c79', 3, 'Only the physician present for the LEAST amount of time may report critical care codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a31ec87f-d2e2-40be-b614-f7421d19afe4', 'fa2b340b-fe3a-47b9-b5ac-b724d31218c7', 0, 'Contemporaneous documentation of start/stop times (or total cumulative time) spent on qualifying critical care activities for that specific patient, consistent with the general time-documentation principle already established for other time-based code families throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f9a688e-3387-4aa0-89cf-7d733224deef', 'fa2b340b-fe3a-47b9-b5ac-b724d31218c7', 1, 'No time documentation is needed since critical care is billed as a flat per-encounter fee regardless of duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bbfd217-5dd5-4c53-8cb3-e55c190c9a08', 'fa2b340b-fe3a-47b9-b5ac-b724d31218c7', 2, 'Only the ICU nursing flow sheet''s documentation is relevant; physician documentation of their own time is unnecessary');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5efaf67-06e3-497b-8a27-03438e60f41d', 'fa2b340b-fe3a-47b9-b5ac-b724d31218c7', 3, 'Critical care time is assumed to be the physician''s entire shift length regardless of actual patient-specific activity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b48957a5-9d99-4ae3-a42c-466a1c1df0f4', 'b210363a-9e9f-4f16-99ce-56834029083d', 0, 'CPT includes distinct prolonged service add-on code structures reflecting different care settings (office/outpatient vs. inpatient/observation vs. nursing facility), each tied to their own respective base E/M code family''s time thresholds, rather than a single universal prolonged-services code applicable across all settings identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('331a59c7-f3e5-429f-b38c-a66498bf7cb0', 'b210363a-9e9f-4f16-99ce-56834029083d', 1, 'The exact same prolonged services add-on code applies identically regardless of care setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8381b059-b58b-4a06-b9bc-7a13eb2fca59', 'b210363a-9e9f-4f16-99ce-56834029083d', 2, 'Prolonged services are never separately coded for inpatient/observation encounters, only office/outpatient visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a173003-d254-4d75-91be-454bec281aca', 'b210363a-9e9f-4f16-99ce-56834029083d', 3, 'Inpatient prolonged services require a completely different, unrelated specialty-specific code system');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('222eb091-084b-4183-97f7-ba52810e5f4d', '5599a817-4343-4c03-a3dd-ceb7484419d9', 0, 'Each encounter (the new admission and the unrelated discharge) is coded independently on its own merits, using the appropriate admission E/M code for the new patient and discharge day management code for the other, unrelated patient, since these are two entirely separate patients with no bearing on each other''s coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfd8cc7a-ea37-4a45-970b-fed60b0eb1b7', '5599a817-4343-4c03-a3dd-ceb7484419d9', 1, 'Only one E/M service may be billed per physician per calendar date, regardless of how many distinct, unrelated patients were involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e160e5a9-39da-4e3e-bb18-7259ff3cf9d8', '5599a817-4343-4c03-a3dd-ceb7484419d9', 2, 'Admission and discharge services for different patients on the same date must always be combined into a single code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f63c455a-8037-4c79-804f-3d1764885320', '5599a817-4343-4c03-a3dd-ceb7484419d9', 3, 'The physician must choose between billing the admission or the discharge, not both, on the same date');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eddc2a2a-b8c1-4dac-bce8-9ac5138d7d6f', '257999f3-fe47-4cf0-a74c-d44447f83174', 0, 'CPT includes specific code(s) addressing same-day admission and discharge as a distinct scenario, rather than requiring separate reporting of both a standard initial hospital care code AND a separate discharge day management code for that single day''s combined service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98b8d314-542a-45bb-9225-ea5a30652130', '257999f3-fe47-4cf0-a74c-d44447f83174', 1, 'Same-day admission and discharge is coded using both the full initial hospital care code AND the full separate discharge management code, stacked together with no special same-day convention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7573054-8bd2-4174-8e21-004e6eb1e18c', '257999f3-fe47-4cf0-a74c-d44447f83174', 2, 'Same-day admission and discharge can never occur or be coded under any CPT convention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d19e3beb-2cac-471c-9c03-39c7511b8de3', '257999f3-fe47-4cf0-a74c-d44447f83174', 3, 'Same-day admission/discharge is always coded as an outpatient observation service regardless of the actual admission status');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e198c751-4bcc-4af3-bd92-a80788761c82', 'bd63ed40-ad0d-42c3-9e1b-ecf08a0c6483', 0, 'Assume all non-office E/M services are billed using the same office/outpatient time-or-MDM leveling framework with no setting-specific distinctions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82b92ca3-b663-43d8-b9c1-c7253b8f6f4b', 'bd63ed40-ad0d-42c3-9e1b-ecf08a0c6483', 1, 'Identify the SPECIFIC care setting and service type (critical care, standard inpatient, same-day admit/discharge, transitional care, care management) actually documented, since each has its OWN distinct code family/time-threshold/documentation-requirement structure rather than a single universal E/M framework applying identically across all settings and service types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6010468d-fe01-45d0-89b6-caa7c55f4731', 'bd63ed40-ad0d-42c3-9e1b-ecf08a0c6483', 2, 'Rely solely on which unit/department the patient is physically located in, without confirming what type of service was actually documented as performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f689ee9-b583-4275-83ad-a46e5acff014', 'bd63ed40-ad0d-42c3-9e1b-ecf08a0c6483', 3, 'Default to critical care coding whenever a patient is located in an ICU, regardless of whether the specific critical care documentation/time requirements are actually met');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c9438d5-8d99-42f8-9f1a-36d24bf5c4f0', '063c87f7-da66-43c6-ae10-9a9f1aadc760', 0, 'Nursing facility E/M codes distinguish initial (comprehensive) visits from subsequent visits, mirroring the general initial-versus-subsequent structure seen in other facility-based E/M code families (e.g., hospital inpatient), with leveling based on time or MDM consistent with current E/M guidelines');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb9d4ccb-384e-42af-8b3e-851c1e3a8e57', '063c87f7-da66-43c6-ae10-9a9f1aadc760', 1, 'Nursing facility visits are coded using the identical office/outpatient E/M codes with no distinct facility-specific code family');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e27abc22-0887-4ba2-a394-cad3e26904eb', '063c87f7-da66-43c6-ae10-9a9f1aadc760', 2, 'Only subsequent nursing facility visits have a CPT code; initial visits must use an unlisted E/M code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d696832a-ec71-48bc-b765-8c83816765d3', '063c87f7-da66-43c6-ae10-9a9f1aadc760', 3, 'Nursing facility E/M coding has no time-or-MDM leveling option, using only a flat per-visit fee');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8ca19cf-36e8-454d-a994-34e7bfe1d474', '797f001d-6050-407a-9438-83811270104a', 0, 'A specific code exists for the federally-mandated periodic comprehensive assessment required in the nursing facility setting, reflecting this distinct regulatory/clinical requirement rather than being folded into a routine subsequent-visit code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb34c259-a24b-4501-ba3b-7bdf7399d5ef', '797f001d-6050-407a-9438-83811270104a', 1, 'Annual assessments are coded identically to any routine subsequent nursing facility visit with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf865740-47eb-4153-bea6-e766f2bdd077', '797f001d-6050-407a-9438-83811270104a', 2, 'Annual nursing facility assessments have no CPT code at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93207d37-5526-4477-827f-b845a1ea01c3', '797f001d-6050-407a-9438-83811270104a', 3, 'Annual assessment codes apply only to newly admitted patients, never existing long-term residents');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b7f072a-46e9-43d7-9f9f-b277335d4653', 'f14281f8-4586-402f-8bae-64ffea4af2b9', 0, 'Home visit E/M codes form their own distinct code family (new vs. established patient, leveled by time or MDM consistent with current guidelines), reflecting the different site-of-service from an office or facility-based visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc0f0810-f826-4e5b-9442-1dc98af34bcd', 'f14281f8-4586-402f-8bae-64ffea4af2b9', 1, 'Home visits are coded using the identical office/outpatient E/M codes with no distinct home-visit-specific code family');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d4b502d-5e4a-4577-bf7f-309c16ca8fee', 'f14281f8-4586-402f-8bae-64ffea4af2b9', 2, 'Home visit codes apply only to hospice patients, never other home-based care scenarios');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e1e2c81-7673-4f34-9060-af4f9087bf64', 'f14281f8-4586-402f-8bae-64ffea4af2b9', 3, 'Home visits can never be coded using medical decision making, only time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d35666a9-74bd-4baa-9b68-bd562c8d63da', 'ee47027f-c23f-4574-974a-7e632e64532d', 0, 'Documentation should reasonably reflect the home setting and any relevant circumstances of care in that setting (as clinically appropriate), consistent with the general principle that documentation should accurately reflect the actual encounter, though the underlying time-or-MDM leveling framework itself doesn''t fundamentally change based on setting alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecd9aa31-5258-43c5-964c-49f11ad22e6d', 'ee47027f-c23f-4574-974a-7e632e64532d', 1, 'Home visits require an entirely different documentation standard unrelated to time or MDM concepts');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6f092d1-04ca-4de2-8a22-5c1deee8ddbc', 'ee47027f-c23f-4574-974a-7e632e64532d', 2, 'No documentation is required for home visits beyond the physician''s own recollection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6aff2f63-9ccb-4803-87c0-61e82ca8d2e5', 'ee47027f-c23f-4574-974a-7e632e64532d', 3, 'Home visit documentation must always include a home safety inspection checklist to be billable at any level');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('694dd961-61f5-4cbe-99ad-45996aea9d21', 'afeca2db-6f7b-4c72-b4f9-e912a272ac49', 0, 'Group visits generally still require individual, patient-specific documentation supporting whatever individual E/M or other applicable code is being reported for EACH patient, since group format doesn''t eliminate the need for encounter-specific, patient-specific documentation to support that patient''s own billed service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('43df6e8f-0028-476d-b5ec-bf70a30f569d', 'afeca2db-6f7b-4c72-b4f9-e912a272ac49', 1, 'A single group visit note covering all patients together, with no patient-specific individual documentation, is fully sufficient to bill each patient''s individual E/M service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfc5ea04-3218-4e4f-b0ef-5572dcf061ca', 'afeca2db-6f7b-4c72-b4f9-e912a272ac49', 2, 'Group visits can never be billed under any CPT code, regardless of format or content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('864b07c9-346a-4762-9fa8-0aefa45bf774', 'afeca2db-6f7b-4c72-b4f9-e912a272ac49', 3, 'Group visit coding depends solely on the total number of patients in the group, not on individual patient documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f344de83-514d-46d9-a6d2-04879311420e', '3b860fda-a076-45db-a91b-82f9b450d781', 0, 'All E/M services, regardless of setting, are fundamentally interchangeable and coded identically once a general ''E/M visit occurred'' is documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4dd956c0-d42f-422f-a2bb-f2ee56d42708', '3b860fda-a076-45db-a91b-82f9b450d781', 1, 'CPT''s E/M section reflects a deliberately setting-and-service-specific structure — accurate coding requires recognizing which SPECIFIC code family (and its own time/MDM/documentation rules) applies to the actual site of service and service type, rather than applying a single, one-size-fits-all E/M coding approach across every clinical context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('085359cc-e30d-463b-890c-4be9f500fab6', '3b860fda-a076-45db-a91b-82f9b450d781', 2, 'Only office/outpatient E/M codes are relevant to real-world coding practice; all other E/M code families are rarely used and can be deprioritized');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94f18c1f-9de8-40d3-9e65-d9b3992cb19d', '3b860fda-a076-45db-a91b-82f9b450d781', 3, 'E/M coding accuracy depends solely on the physician''s specialty, not the actual site of service or service type documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c101bb3-6e99-4f20-a545-6035a0949a9e', '3a40d805-a7e8-4ecd-b74c-fc442f9b55ae', 0, 'Age has no bearing on anesthesia coding beyond the physical status modifier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f7ce50a-812a-47b5-a416-334ab4b52d66', '3a40d805-a7e8-4ecd-b74c-fc442f9b55ae', 1, 'Qualifying circumstances add-on codes (already discussed in Paper 1) specifically address extremes of age as a complicating factor for anesthesia administration, reported in addition to the base anesthesia code and physical status modifier when documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a547df40-42a0-43e3-855e-343040e0c678', '3a40d805-a7e8-4ecd-b74c-fc442f9b55ae', 2, 'Age is captured exclusively through a completely separate, unrelated code system with no connection to the anesthesia base code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba72acf4-05f4-44a4-ab7d-9182e0d19112', '3a40d805-a7e8-4ecd-b74c-fc442f9b55ae', 3, 'Extreme age automatically changes which root operation is coded, similar to ICD-10-PCS logic');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('214efaf0-a21e-4e4f-b89c-2950eddd5a33', 'f9a706f4-799c-4f0c-b9d4-3bf7967d622c', 0, 'The same anesthesia code (for that procedure/anatomic region) applies regardless of patient age, since anesthesia codes are structured by procedure/region rather than by patient age directly — age-related complexity, when it exists, is instead captured via the qualifying circumstances add-on code, not a different base anesthesia code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a0d9d78-3af0-4f6b-9867-5eb94ab58a6d', 'f9a706f4-799c-4f0c-b9d4-3bf7967d622c', 1, 'Pediatric patients always require an entirely separate, parallel set of anesthesia base codes distinct from the adult anesthesia code set');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('956ccd35-aef5-445b-9f77-ac172e7be65a', 'f9a706f4-799c-4f0c-b9d4-3bf7967d622c', 2, 'Pediatric anesthesia can never be coded using the standard CPT anesthesia code set');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b98ca9c-a021-425c-8c7a-0713f0442d8d', 'f9a706f4-799c-4f0c-b9d4-3bf7967d622c', 3, 'Base anesthesia units change automatically based on patient age without any specific add-on code needed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26a0d500-bab2-45d3-ab33-4aaecb90aac7', '1b18653c-2f9a-4265-91b4-0d1e31352b5b', 0, 'The appropriate anesthesia code for the specific endoscopic procedure is reported, generally with the MAC concept reflected through appropriate documentation/qualifying modifier conventions rather than a wholly separate code set from general anesthesia for the same procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20ddb6a6-9c7c-4041-8f6e-fe773956a93a', '1b18653c-2f9a-4265-91b4-0d1e31352b5b', 1, 'MAC always uses a completely different, unrelated set of base anesthesia codes from general anesthesia for the identical procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9295114f-a474-418b-a027-f98befd7c978', '1b18653c-2f9a-4265-91b4-0d1e31352b5b', 2, 'MAC can never be coded for endoscopic procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fda21ec-4d20-4ad9-b8a7-d3010b885093', '1b18653c-2f9a-4265-91b4-0d1e31352b5b', 3, 'MAC anesthesia has no relationship to physical status modifiers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('613a1178-fa9b-4f21-9738-c7b2136c32af', 'ca0d227c-5fed-4f58-974f-5c39f9c3a469', 0, 'The anesthesia record should document that total body hypothermia was actually utilized as part of the anesthetic management, since this qualifying circumstance code requires that the specific technique actually be documented as performed, not assumed based on the general complexity of the underlying surgery');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24fc61a5-115e-452f-b715-585d593266a6', 'ca0d227c-5fed-4f58-974f-5c39f9c3a469', 1, 'No specific documentation is needed since hypothermia is assumed for any complex cardiac case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('562427a2-da50-4eb2-974d-d8843b9e4b9b', 'ca0d227c-5fed-4f58-974f-5c39f9c3a469', 2, 'Hypothermia qualifying circumstances codes apply automatically to all cardiac surgery regardless of whether hypothermia was actually used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66c414fe-245d-4581-8590-18a0d9567915', 'ca0d227c-5fed-4f58-974f-5c39f9c3a469', 3, 'Qualifying circumstances codes never require any specific supporting documentation beyond the base anesthesia code''s own documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3feea3b-ceca-48ba-b40e-bbb48388f94b', 'b34c546d-8035-4540-92b7-2ae53d3ddbd4', 0, 'Following the same multiple-procedures-same-session anesthesia coding principle already established in Paper 1, the anesthesia code with the highest base unit value among the procedures performed is generally reported, with time calculated for the entire combined session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79475806-4ddc-41c2-8fc5-dab0b9ad2cf5', 'b34c546d-8035-4540-92b7-2ae53d3ddbd4', 1, 'Two completely separate anesthesia claims are always submitted for the diagnostic and therapeutic portions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b56074e0-7fa3-4c41-856f-a679257984d7', 'b34c546d-8035-4540-92b7-2ae53d3ddbd4', 2, 'Only the diagnostic procedure''s anesthesia code is ever reported, regardless of the therapeutic portion performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b567dd9-788f-4124-9441-4c82e62a0290', 'b34c546d-8035-4540-92b7-2ae53d3ddbd4', 3, 'Anesthesia coding for combined diagnostic-then-therapeutic procedures in one session is never addressed by any CPT convention');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77baa6d1-6e42-4dab-90bf-2cceca8f4cf3', '1ca2a035-ef34-405a-90ad-4eebb33d77b9', 0, 'Always select the anesthesia code with the highest base unit value available, regardless of the actual procedure/region documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5d26ece-3f29-49ba-9ab3-dafd0322c32e', '1ca2a035-ef34-405a-90ad-4eebb33d77b9', 1, 'Match the SPECIFIC procedure/anatomic region, patient physical status, any qualifying circumstances actually documented, and the anesthesia technique''s clinical role (primary anesthetic vs. postoperative pain adjunct) to the correct combination of base code, physical status modifier, and qualifying circumstances add-on code(s) — since anesthesia coding accuracy depends on correctly combining several distinct, independently-documented elements, not a single code chosen in isolation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bbc400af-9df4-46ac-8c46-6f5f46729191', '1ca2a035-ef34-405a-90ad-4eebb33d77b9', 2, 'Anesthesia coding requires only the base procedure code, with modifiers and qualifying circumstances being optional stylistic additions with no real bearing on accurate reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba719cb0-b671-4273-a452-1bd2de2da8cf', '1ca2a035-ef34-405a-90ad-4eebb33d77b9', 3, 'Assume every anesthesia service is billed identically regardless of patient status, technique, or complicating circumstances');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91958850-fb84-4afd-9013-f9b7fc52fd6e', 'ea377ec0-bdeb-4876-a54a-4193032d0d17', 0, 'Anesthesia for ECT (typically brief general anesthesia for a very short procedure) has its own specific, distinct anesthesia code reflecting the specific procedure category, consistent with the general principle that anesthesia codes map to specific procedure/region categories rather than a single generic ''general anesthesia'' code applying uniformly regardless of the underlying procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9611158-1ca1-4038-9869-b19e7109f5ad', 'ea377ec0-bdeb-4876-a54a-4193032d0d17', 1, 'Anesthesia for ECT is coded identically to anesthesia for a major abdominal surgery');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64c06ad2-7f4b-4b36-9d27-24c8e53eb5fd', 'ea377ec0-bdeb-4876-a54a-4193032d0d17', 2, 'ECT anesthesia is never separately coded from the ECT procedure itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1742f541-a5b4-4cd9-8d73-cc9d2d49f00b', 'ea377ec0-bdeb-4876-a54a-4193032d0d17', 3, 'Anesthesia for brief procedures like ECT can never be billed under the standard anesthesia base-unit-plus-time formula');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('500aa258-9fd1-49b9-89b4-e9bb6cdd107f', '45aa0964-d279-46a8-b5fd-65976903c1f6', 0, 'Anesthesia for diagnostic imaging procedures (like MRI) has its own applicable anesthesia code category, distinct from anesthesia for surgical/interventional procedures, reflecting that anesthesia services extend beyond the operating room to diagnostic imaging contexts requiring anesthesia support');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16a6fe2e-ebfd-43e6-8fd9-62a64b0aba7d', '45aa0964-d279-46a8-b5fd-65976903c1f6', 1, 'Anesthesia is never provided or coded for diagnostic imaging procedures under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('135bc37b-42a4-45c4-9d64-594e8a0b49cc', '45aa0964-d279-46a8-b5fd-65976903c1f6', 2, 'MRI anesthesia is coded using the same code as anesthesia for an open abdominal surgery');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca048042-8f64-4fcd-b515-e881ac5aba6d', '45aa0964-d279-46a8-b5fd-65976903c1f6', 3, 'Anesthesia for diagnostic imaging is included in the radiology procedure code with no separate anesthesia code ever applicable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eb08507-7aea-458a-9859-48ab5f259642', '8e77052d-1935-4fa1-975f-222247fcfbc7', 0, 'The anesthesia record should clearly document the specific procedure/context for which anesthesia was provided (e.g., MRI, radiation therapy), since the anesthesia code selected should reflect the actual underlying procedure/context, not simply a generic ''anesthesia service'' entry with no procedure-specific detail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30ef8494-f112-4990-a907-edf36db3e9ef', '8e77052d-1935-4fa1-975f-222247fcfbc7', 1, 'No procedure-specific documentation is needed since all anesthesia services are coded identically regardless of the underlying procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cad08ee5-b30e-4881-b5d5-b33a13dc09d3', '8e77052d-1935-4fa1-975f-222247fcfbc7', 2, 'Anesthesia records for diagnostic/non-surgical contexts require no time documentation, unlike surgical anesthesia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e75a94d3-88d1-4bc3-83bd-12432a75d164', '8e77052d-1935-4fa1-975f-222247fcfbc7', 3, 'Anesthesia documentation for non-surgical procedures is governed by an entirely separate, unrelated documentation standard from surgical anesthesia documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eea06e6c-9314-42fb-84af-64d006d34c64', 'b3cb3265-548a-4adc-9c48-3dee2a3bbf69', 0, 'If, after careful review of the available anesthesia code categories and their descriptors, no existing code accurately reflects the specific procedure/region for which anesthesia was provided, an unlisted anesthesia procedure code (with an appropriate special report) may be the correct approach — consistent with the general unlisted-procedure-code principle already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da850f76-a368-480b-b101-35e78cd85167', 'b3cb3265-548a-4adc-9c48-3dee2a3bbf69', 1, 'Unlisted anesthesia procedure codes never exist; every anesthesia scenario must always fit an existing specific code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8cce312-4614-4419-9712-cd996549fda6', 'b3cb3265-548a-4adc-9c48-3dee2a3bbf69', 2, 'The closest-sounding existing anesthesia code should always be used instead of ever considering an unlisted code, regardless of actual fit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('585f4762-28ab-42d7-9c8d-d9a1ef0fde96', 'b3cb3265-548a-4adc-9c48-3dee2a3bbf69', 3, 'Unlisted anesthesia codes apply only to obstetric anesthesia scenarios');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7ffacef-1a87-485a-8073-9d7444904a1d', 'f236683c-98c9-44a0-9fa0-60c5aeb2397a', 0, 'Fracture care codes (whether closed treatment without manipulation, closed treatment with manipulation, or open treatment) generally include the initial cast/splint application and a defined period of related follow-up care as part of a global fracture care package, similar in concept to the global surgical package already discussed generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a26cdce8-eb93-41c2-a3f2-7ce8b8f05d81', 'f236683c-98c9-44a0-9fa0-60c5aeb2397a', 1, 'Fracture care is always billed per individual office visit, with no global/bundled concept ever applying');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2f3ebf4-3feb-4ea7-b907-b60220b1f9ff', 'f236683c-98c9-44a0-9fa0-60c5aeb2397a', 2, 'Fracture care codes never include any follow-up care, requiring every subsequent visit to be separately billed regardless of relatedness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3eb2bf98-716f-4078-b1c0-6291d264a108', 'f236683c-98c9-44a0-9fa0-60c5aeb2397a', 3, 'All fracture treatment, regardless of technique, is coded using a single universal fracture care code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b261d48-5042-4ac4-a392-9de8b3498eb3', 'a2898ce5-63fb-4c43-b8fb-ee97e5fe1206', 0, 'These reflect genuinely different levels of intervention — without manipulation (simple immobilization, no reduction), with manipulation (reduction performed without surgical incision), and open treatment (surgical exposure of the fracture site, e.g., for ORIF) — each with its own specific code reflecting the actual technique performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8c0c940-97f4-45ad-a0f7-0a37e335d870', 'a2898ce5-63fb-4c43-b8fb-ee97e5fe1206', 1, 'These three terms are interchangeable synonyms for the same fracture treatment approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20292424-5cdd-48c5-b768-e41bc3dd4544', 'a2898ce5-63fb-4c43-b8fb-ee97e5fe1206', 2, 'Only ''open treatment'' has a CPT code; the other two closed-treatment categories have no corresponding codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('602ef866-798e-4010-96a8-2641c22d975f', 'a2898ce5-63fb-4c43-b8fb-ee97e5fe1206', 3, 'The distinction applies only to lower extremity fractures, never upper extremity fractures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd9812db-69c1-40f6-af83-c07a8f952802', '8e07457f-f343-46ed-af1a-5e91994922b9', 0, 'External fixation application may have its own separately reportable code, in addition to the fracture care code, when it represents additional, distinct work beyond the fracture reduction itself, consistent with the general principle that genuinely distinct additional procedural components may be separately reportable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfbc3b03-1a8e-4d10-9e1e-4a993eb6af32', '8e07457f-f343-46ed-af1a-5e91994922b9', 1, 'External fixation is always included in the base fracture care code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c11aeef2-db45-4949-bd73-1e1975b1299e', '8e07457f-f343-46ed-af1a-5e91994922b9', 2, 'External fixation application is coded using the same code as an internal fixation (ORIF) procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f08c4735-54f6-4d9c-99bf-071f8357ede3', '8e07457f-f343-46ed-af1a-5e91994922b9', 3, 'Fracture care and external fixation can never both be performed in the same operative session');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5e46fb3-613c-4a38-92c6-4cf9e25259c5', '8ce303a8-5004-4411-aee2-8c4fd5397a5b', 0, 'The diagnostic arthroscopy is generally considered bundled into the more extensive therapeutic (surgical) arthroscopic procedure performed at the same session, consistent with the general diagnostic-converted-to-therapeutic bundling principle already established for other modalities (e.g., diagnostic-to-therapeutic endoscopy conversions)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3157b50-e5f8-476d-93a2-3aaad69f13cc', '8ce303a8-5004-4411-aee2-8c4fd5397a5b', 1, 'Both the diagnostic and therapeutic arthroscopy codes are always reported together in full');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5154f487-60b3-4a7b-b7cf-40436fe8f729', '8ce303a8-5004-4411-aee2-8c4fd5397a5b', 2, 'Only the diagnostic arthroscopy code is ever reported, regardless of therapeutic work performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1503954-14e9-41f1-b8c8-ea00c7dd5ffb', '8ce303a8-5004-4411-aee2-8c4fd5397a5b', 3, 'Diagnostic and therapeutic arthroscopy of the same joint can never occur in the same operative session');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('696b991c-74ed-46b7-8d6e-f75c15aef6ec', 'f65a5796-8a91-4494-80b1-fa2fb4679b8c', 0, 'Each distinct arthroscopic procedure performed may be separately reportable (subject to any applicable NCCI edits/bundling for that specific code combination), since these represent genuinely distinct surgical interventions on different structures within the joint, though some combinations may be bundled per specific NCCI edits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38c2970f-ae24-45b8-abd5-550d19136a13', 'f65a5796-8a91-4494-80b1-fa2fb4679b8c', 1, 'All arthroscopic procedures on the same joint during the same session are always combined into a single code regardless of how many distinct structures were treated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f73d4dc9-bfc8-4f0e-878d-b65ac6913a7d', 'f65a5796-8a91-4494-80b1-fa2fb4679b8c', 2, 'Only one arthroscopic procedure per joint per session may ever be coded, regardless of how many distinct structures were addressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50dc86a7-1c12-4eaa-a529-3a370636ab0e', 'f65a5796-8a91-4494-80b1-fa2fb4679b8c', 3, 'Arthroscopic procedures on the same joint always require two entirely separate operative sessions to each be separately coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('162cce73-856b-4800-96b7-e8bfbd1f5223', '7d403601-8b89-48bf-ab8b-380e22e53da0', 0, 'Arthroscopic and open rotator cuff repair are coded using distinct codes reflecting the different surgical approach/technique, similar to how other procedures throughout this content distinguish coding by approach/technique actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f88d48eb-93d1-4bb3-8edc-a6ac51ab100d', '7d403601-8b89-48bf-ab8b-380e22e53da0', 1, 'Arthroscopic and open rotator cuff repair are always coded identically regardless of approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('250a37a6-194a-458f-8632-efd063b012e0', '7d403601-8b89-48bf-ab8b-380e22e53da0', 2, 'Only open rotator cuff repair has a CPT code; arthroscopic repair must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f91f0a2e-1d5e-4e0a-a41c-6e45a6f04de5', '7d403601-8b89-48bf-ab8b-380e22e53da0', 3, 'Rotator cuff repair coding depends solely on the patient''s age, not the surgical approach used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c23dbf44-e4ba-47ef-a472-b3973a28eff0', '2136d105-7a0e-4513-8062-304cf281d5e3', 0, 'CPT includes specific codes reflecting the number of leads placed (single vs. dual chamber) and whether it''s a new system or involves a pre-existing component, since pacemaker system coding depends on these specific documented details rather than a single universal ''pacemaker implant'' code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a1bd960-a9e4-4eaa-964b-f8fb4dbe9170', '2136d105-7a0e-4513-8062-304cf281d5e3', 1, 'All pacemaker implantations are coded using a single universal code regardless of the number of leads or system configuration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28c64f08-c896-4289-a053-b4e7d358d6a0', '2136d105-7a0e-4513-8062-304cf281d5e3', 2, 'Pacemaker generator and lead placement are always coded as two entirely separate, unrelated procedures with no combined-system code ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ba379e5-3f61-4d25-a3a6-98563a45b58f', '2136d105-7a0e-4513-8062-304cf281d5e3', 3, 'Pacemaker coding depends solely on the patient''s underlying arrhythmia diagnosis, not the device system configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18d97ead-40fd-4ac2-9dcd-76eaf8d7cf35', '1373936c-1064-4132-b3f8-4092bd5eedd5', 0, 'A specific code exists for generator replacement alone (without lead replacement), distinct from a code for initial full-system implantation (generator plus new leads), reflecting the different scope of work when only the generator is being exchanged');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89b1fee1-2c17-4e34-b060-d2a119c4807a', '1373936c-1064-4132-b3f8-4092bd5eedd5', 1, 'Generator-only replacement is coded identically to a full initial system implantation with new leads');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('663eb66c-1c08-4f03-929a-30df0531d8e9', '1373936c-1064-4132-b3f8-4092bd5eedd5', 2, 'Generator replacement can never be coded separately from lead placement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3f42cb7-b394-455b-8f34-af97e06ad7b2', '1373936c-1064-4132-b3f8-4092bd5eedd5', 3, 'Testing of existing leads during a generator replacement is never separately relevant to coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1823ace-bd48-460e-ab1a-a00de960ecbf', 'dc73fdef-77a9-4d5e-b466-69f4470ced30', 0, 'ICD systems have their own distinct code family separate from pacemaker codes, reflecting the different device technology/function (defibrillation capability in addition to or instead of pacing), even though the implantation technique may involve similarly-placed leads');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('208d3b9b-fde2-4fdc-b587-49733504427b', 'dc73fdef-77a9-4d5e-b466-69f4470ced30', 1, 'ICD and pacemaker systems are coded identically since both involve implanting a device with leads');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1c619a6-48c7-4e26-a417-a56e518d5293', 'dc73fdef-77a9-4d5e-b466-69f4470ced30', 2, 'ICD implantation is coded using the same codes as a loop recorder implantation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('681b2856-2232-4238-97b6-942ed689c372', 'dc73fdef-77a9-4d5e-b466-69f4470ced30', 3, 'ICD system coding depends solely on device battery life, not device type/function');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d9c9dd4-c1b4-4787-bd38-ab80c2641e63', 'fe073403-a6a0-4079-9d83-0484f6e9e8d5', 0, 'TURP has its own specific code reflecting this particular endoscopic surgical technique and approach (via the urethra) for prostate tissue removal, distinct from an open or laparoscopic prostatectomy approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('346f8060-b455-4884-874e-69dbae881784', 'fe073403-a6a0-4079-9d83-0484f6e9e8d5', 1, 'TURP is coded identically to an open radical prostatectomy for prostate cancer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('76ea2831-8eb5-4795-8654-75e858c0b7d1', 'fe073403-a6a0-4079-9d83-0484f6e9e8d5', 2, 'TURP has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6258bec4-5030-4266-987a-bed41a1ae593', 'fe073403-a6a0-4079-9d83-0484f6e9e8d5', 3, 'TURP coding depends solely on the patient''s PSA level, not the actual procedure performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
