INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c09fabd-a8bc-463c-842c-490f90c60b03', '043705e6-bfcf-4537-aa7b-8c55ad27e199', 0, 'Cystoscopy with ureteral stent placement has its own specific combined code reflecting both the endoscopic visualization and the stent placement performed together, distinct from a diagnostic cystoscopy alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c833230-a8e1-4c66-87f4-8767a909a86f', '043705e6-bfcf-4537-aa7b-8c55ad27e199', 1, 'Cystoscopy and ureteral stent placement are always coded as entirely separate, unrelated procedures with no combined code ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3acad3cc-8c86-4e62-9d5b-119b976e8aec', '043705e6-bfcf-4537-aa7b-8c55ad27e199', 2, 'Ureteral stent placement is coded identically to a urinary catheter placement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e34a7238-88bb-4911-909e-1d7279652586', '043705e6-bfcf-4537-aa7b-8c55ad27e199', 3, 'Cystoscopy with stent placement requires an unlisted procedure code in all cases');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
