INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a3e5e7b-d68c-4545-a359-1d7033b5eb39', '6ca6644a-accd-4d7a-8c68-ccc9b3cde8cf', 0, 'ESWL (a noninvasive, externally-applied shock-wave technique to fragment a stone) has its own specific code, distinct from ureteroscopic procedures (an internal, endoscopic approach to directly access and fragment/remove a stone), reflecting genuinely different techniques for treating the same general condition (urolithiasis)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('561a5f47-e966-456f-bc2c-6ce4c8f25eb2', '6ca6644a-accd-4d7a-8c68-ccc9b3cde8cf', 1, 'ESWL and ureteroscopic stone treatment are coded identically since both address kidney stones');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c134f66b-23e2-4061-8ef3-1c19cd1aa5d5', '6ca6644a-accd-4d7a-8c68-ccc9b3cde8cf', 2, 'ESWL is coded using the same code as a diagnostic renal ultrasound');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87f93a17-9217-46e2-b7b8-ead1690fb4aa', '6ca6644a-accd-4d7a-8c68-ccc9b3cde8cf', 3, 'Ureteroscopic stone removal has no distinct CPT code from a routine cystoscopy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
