INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a9549a4-24a2-483b-a57f-87f521eb2112', '5e2f552a-aec4-411a-800b-39a5c06e2ba7', 0, 'CPT commonly distinguishes tonsillectomy (and adenotonsillectomy) codes by patient age (e.g., under vs. over a certain age threshold), reflecting recognized differences in typical procedure complexity/technique considerations between pediatric and adult patients for this specific procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fa0aa14-0e37-4999-873a-7be0fcff02fb', '5e2f552a-aec4-411a-800b-39a5c06e2ba7', 1, 'Tonsillectomy is coded identically regardless of patient age');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('874222ee-5141-45c2-b91c-b672fdfe3682', '5e2f552a-aec4-411a-800b-39a5c06e2ba7', 2, 'Tonsillectomy has no distinct code from a routine throat culture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da7e2a36-f4a5-415f-8704-cd7b69295c4e', '5e2f552a-aec4-411a-800b-39a5c06e2ba7', 3, 'Age-based tonsillectomy code distinctions apply only to adenoidectomy, never tonsillectomy itself');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
