INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77c836c7-7c64-418f-9db7-5e1737b8ba8d', 'ef5195a6-d53c-4d4c-a2bb-424e5b15672e', 0, 'This procedure has its own specific code(s), potentially distinguishing whether general anesthesia was required (as is typical for young pediatric patients) versus local/topical anesthesia (as might occur in an older child or adult), reflecting the same anesthesia-related documentation relevance already discussed generally for procedure coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('280e4dcb-4e4e-4066-89e9-be05e62b8106', 'ef5195a6-d53c-4d4c-a2bb-424e5b15672e', 1, 'Tympanostomy tube placement is coded identically to a routine ear examination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4cb54465-3a06-4258-b362-152e45007e9b', 'ef5195a6-d53c-4d4c-a2bb-424e5b15672e', 2, 'This procedure has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89c85681-88e0-40ea-87db-f8f435d12f86', 'ef5195a6-d53c-4d4c-a2bb-424e5b15672e', 3, 'Tympanostomy tube placement coding depends solely on which ear (left/right) is treated, with no other coding distinctions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ea07503-e0ca-4e2b-ab41-9dd89983f539', '3e4437ca-1817-4a78-ad03-11de8c9410ac', 0, 'The septoplasty itself is coded based on the functional/therapeutic procedure performed, with the presence of a functional indication (breathing impairment) generally being what supports medical necessity/coverage for the septoplasty portion — while any purely cosmetic component (e.g., a concurrent rhinoplasty for appearance alone) would be evaluated and potentially coded/billed separately as a distinct, medical-necessity-independent cosmetic procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34e175ef-b1e0-4e2d-998d-7ca2a8233efb', '3e4437ca-1817-4a78-ad03-11de8c9410ac', 1, 'Septoplasty is never covered or coded when any cosmetic concern is also present, regardless of documented functional impairment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a440977b-f7f9-44c0-b5af-115351b0f7fb', '3e4437ca-1817-4a78-ad03-11de8c9410ac', 2, 'Cosmetic and functional nasal procedures are always coded identically with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65a7cec4-3397-4b2b-8b84-5244e98fb33e', '3e4437ca-1817-4a78-ad03-11de8c9410ac', 3, 'Septoplasty has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
