INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('677353ce-eb85-49c4-9688-30c39816e946', 'ad079401-7e9a-4f92-a347-53a10b103095', 0, 'Each distinct sinus procedure performed is generally separately reportable (per the specific sinus/procedure combination actually performed), subject to any applicable NCCI edits for specific code combinations, since these represent genuinely distinct anatomic sites/procedures within the same general surgical session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('396ce741-7e49-49e0-8599-7e4601d0f166', 'ad079401-7e9a-4f92-a347-53a10b103095', 1, 'All FESS procedures regardless of how many sinuses are addressed are combined into a single universal code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e6cf935-cbb0-46c1-9038-52dd9d850ec5', 'ad079401-7e9a-4f92-a347-53a10b103095', 2, 'Only one sinus procedure per FESS session may ever be coded, regardless of how many sinuses were actually addressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b55ef052-81a1-4e0a-9a59-2cb3a85f84aa', 'ad079401-7e9a-4f92-a347-53a10b103095', 3, 'FESS procedures on different sinuses always require separate operative sessions to each be coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8122369f-3975-44a2-9c3d-707153e8bac2', '4a60c330-b942-4563-8656-4025f1412bc4', 0, 'Assume all procedures within the same general organ system are interchangeable and coded identically regardless of the specific technique/approach/extent documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('483cd9e2-2435-4187-8e34-cf4adf80f18a', '4a60c330-b942-4563-8656-4025f1412bc4', 1, 'Consistently apply the same underlying analytical approach already established throughout this content: identify the SPECIFIC documented technique, approach, anatomic extent, device configuration, and whether the procedure is a distinct component or bundled part of a more comprehensive procedure — then match those specifics to the code descriptor that accurately reflects what was actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62ccf644-9d5c-47c6-9974-5982d977d2fd', '4a60c330-b942-4563-8656-4025f1412bc4', 2, 'Rely on the CPT code number ranges alone (e.g., assuming consecutive numbers are always interchangeable) without reading the actual code descriptors');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('759444aa-46f8-403f-8167-99ddb6959d32', '4a60c330-b942-4563-8656-4025f1412bc4', 3, 'Default to an unlisted procedure code whenever a procedure involves more than one anatomic structure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03c1be1a-daae-4017-b6b0-eba3a981d6c6', '67abe848-7f91-4e09-b063-6e7612b6adad', 0, 'PICC line placement has its own specific code reflecting this distinct central venous access technique (a catheter inserted peripherally but terminating centrally), separate from codes for simple peripheral IV access, which is generally not separately coded as its own procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40bd756a-05b1-4cf6-826b-7764cbc347a5', '67abe848-7f91-4e09-b063-6e7612b6adad', 1, 'PICC line placement is coded identically to a routine peripheral IV start');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7bdea94-a4b2-4f5b-bc47-b5be1e66645e', '67abe848-7f91-4e09-b063-6e7612b6adad', 2, 'PICC lines are coded using the same code as a surgically implanted central venous port');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28616d1a-542c-48cd-a6b9-2e6fb6954613', '67abe848-7f91-4e09-b063-6e7612b6adad', 3, 'PICC line placement has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19beca07-9ee2-4e0f-a7ec-05e427124b57', '1508fbdc-fe60-480c-81c8-102dc54c5a01', 0, 'Tunneled catheters with a subcutaneous port have their own specific code, distinct from both PICC lines and non-tunneled (percutaneously placed, non-tunneled) central venous catheters, reflecting the different technique/device configuration (tunneling and port placement) involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d00af9e6-4a7a-4cf6-8d7d-9adb88eb1886', '1508fbdc-fe60-480c-81c8-102dc54c5a01', 1, 'All central venous access devices, regardless of tunneling or port configuration, are coded identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca0b731f-fdde-418e-8306-960cb5ec7430', '1508fbdc-fe60-480c-81c8-102dc54c5a01', 2, 'Port placement is coded using the same code as a routine peripheral IV start');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d37bc89-35ca-4e62-bc1b-b92d23174947', '1508fbdc-fe60-480c-81c8-102dc54c5a01', 3, 'Tunneled catheter placement has no distinct code from a routine venipuncture for blood draw');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5497a5a5-97b9-4670-ad2e-ab3cc816d647', '5420a0d1-edbc-4171-bf5b-54f815cf92ae', 0, 'Ultrasound guidance for vascular access may have its own separately reportable code, when the specific central line placement code doesn''t already bundle guidance into its own descriptor — consistent with the general imaging-guidance bundling principle already established repeatedly throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('283bb172-7822-4f6e-a544-156a2f1b56b6', '5420a0d1-edbc-4171-bf5b-54f815cf92ae', 1, 'Imaging guidance for vascular access is never separately reportable under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a6932d2-3338-4c91-a313-8859c48d9e40', '5420a0d1-edbc-4171-bf5b-54f815cf92ae', 2, 'Imaging guidance is always bundled into every central line placement code regardless of that code''s own descriptor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8c387e4-e6c9-43de-9e7e-1733d2973cb1', '5420a0d1-edbc-4171-bf5b-54f815cf92ae', 3, 'Ultrasound guidance for vascular access requires an entirely separate anesthesia code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ce63049-30bf-43c2-818f-d3f8b854550c', '980885a2-910e-4564-9f72-224fdd3d2adb', 0, 'Angioplasty (vessel dilation) and stent placement may each have distinct code components (or a combined code, depending on the specific vessel/procedure structure), reflecting the same combined-versus-component coding analysis already established for other multi-step interventional procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b8cdf68-0450-4eb1-a384-9bf535b1df72', '980885a2-910e-4564-9f72-224fdd3d2adb', 1, 'Angioplasty and stenting are always coded as two entirely separate, unrelated procedures with no combined-code option ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('259c6ed1-91c0-4cec-a555-d0b642c14ce2', '980885a2-910e-4564-9f72-224fdd3d2adb', 2, 'Only the stent placement is coded; angioplasty performed to enable stent placement is never separately considered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acd9b7d4-5e54-4e1d-a588-61838444ec4c', '980885a2-910e-4564-9f72-224fdd3d2adb', 3, 'Peripheral angioplasty with stenting has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da87555d-1ec9-40b0-ac75-ccd4676945b1', 'ee79a8bb-12d2-4069-b8f2-a8635c6a7c0b', 0, 'Following the same diagnostic-converted-to-therapeutic bundling principle already established for other modalities (GI endoscopy, arthroscopy), the diagnostic angiogram of the SAME vascular territory being treated is generally considered bundled into the therapeutic intervention, though a diagnostic angiogram of a DIFFERENT, unrelated territory not proceeding to intervention may be separately reportable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7626e169-6949-45fe-8f0a-eb0448353604', 'ee79a8bb-12d2-4069-b8f2-a8635c6a7c0b', 1, 'The diagnostic angiogram is always separately, fully reportable in addition to the therapeutic intervention regardless of vascular territory overlap');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('395a8abe-ea2e-49cb-b31f-48c4a4968009', 'ee79a8bb-12d2-4069-b8f2-a8635c6a7c0b', 2, 'Only the diagnostic angiogram is ever coded, with the therapeutic intervention considered part of it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf3e46f7-3f23-4f05-b206-16c25227a9d1', 'ee79a8bb-12d2-4069-b8f2-a8635c6a7c0b', 3, 'Diagnostic angiography and therapeutic intervention can never occur in the same session under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de3d5312-a21f-46d2-8a22-b9aef4bdf556', '9108923e-97b3-440b-8655-49ab61da5491', 0, 'Assume vascular access procedures are always coded using a single combined code regardless of the specific device, technique, or number of distinct interventions performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('308d1b12-7235-49af-b967-f472aa24ab42', '9108923e-97b3-440b-8655-49ab61da5491', 1, 'Apply the same core analytical discipline already established throughout this content — identify the specific device/technique (tunneled vs. non-tunneled, PICC vs. port), whether imaging guidance is bundled or separate per that code''s descriptor, and whether diagnostic and therapeutic components in the same session represent bundled or separately reportable work — then match to the precise code descriptor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04e0b902-b05c-4114-8684-d09ccbef26c8', '9108923e-97b3-440b-8655-49ab61da5491', 2, 'Vascular access procedures require no code-selection analysis since they are always billed as a flat facility fee with no physician-reportable CPT code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f207ee26-6300-4b94-bf5d-2d123cae789a', '9108923e-97b3-440b-8655-49ab61da5491', 3, 'Rely on the interventional radiologist''s own preferred shorthand terminology rather than reviewing the actual documented technique against code descriptors');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c255dd26-f196-4a23-b7aa-5688eb9098bf', '596357dd-5b8a-4bb1-8399-65b203b0d20a', 0, 'Removal of a tunneled catheter/port has its own specific code, distinct from the insertion code, reflecting that removal is a genuinely separate procedural event from placement — consistent with the general insertion-versus-removal coding distinction already established for other devices throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94684954-d16d-4ef4-84f4-9cd47921d2d7', '596357dd-5b8a-4bb1-8399-65b203b0d20a', 1, 'Removal is always included in the original insertion code''s global period indefinitely, regardless of how much later removal occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dc60e93-83aa-4392-b638-f0ffc5b43648', '596357dd-5b8a-4bb1-8399-65b203b0d20a', 2, 'Port removal is coded identically to port insertion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3175229d-40ff-4cd0-9d51-43833a2c0636', '596357dd-5b8a-4bb1-8399-65b203b0d20a', 3, 'Port removal has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('085833db-2a6a-40b7-b357-206687f9907b', 'b6fa3302-336a-4e9d-a37b-80e0fddf61bc', 0, 'AV graft creation (using synthetic material) has its own specific code, distinct from AV fistula creation (direct native vessel connection), reflecting the different technique/material involved even though both serve the same general dialysis-access purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8eec8886-955b-4f77-a0b9-611af3d36283', 'b6fa3302-336a-4e9d-a37b-80e0fddf61bc', 1, 'AV grafts and AV fistulas are coded identically since both create dialysis access');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3792f96-402e-481b-a4b8-c5e7fe98267e', 'b6fa3302-336a-4e9d-a37b-80e0fddf61bc', 2, 'AV graft placement has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4677f1f-051f-408f-9643-23d29ce799d3', 'b6fa3302-336a-4e9d-a37b-80e0fddf61bc', 3, 'The distinction between graft and fistula has no bearing on CPT code selection, only on which vessels are used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf4f2707-eebf-407e-a781-a50deed339fc', '9c4d40b5-53c3-4ea4-b3e1-741200e7cbb4', 0, 'Revision and thrombectomy procedures on an existing dialysis access have their own specific codes, distinct from the original creation code, reflecting that these represent separate, later procedural events addressing access dysfunction rather than being included in the original creation procedure''s global period indefinitely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19499049-3e8f-4a2b-bda5-cb1cb752084c', '9c4d40b5-53c3-4ea4-b3e1-741200e7cbb4', 1, 'Revision/thrombectomy is always included in the original AV fistula/graft creation code''s global period regardless of how much later it occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fe9a83b-9d75-41f2-af1f-0268cbdc19a3', '9c4d40b5-53c3-4ea4-b3e1-741200e7cbb4', 2, 'AV access revision is coded identically to the original creation procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6ef59cd-13bb-4d6e-b206-fee594c9cfc2', '9c4d40b5-53c3-4ea4-b3e1-741200e7cbb4', 3, 'Thrombectomy of a dialysis access has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a563f736-e329-4e38-949f-0212a1db003c', 'd19e5b59-ad19-4e46-80d5-41adb9298e75', 0, 'Open and endoscopic carpal tunnel release have distinct codes reflecting the different surgical approach, consistent with the recurring approach-specificity coding theme already established throughout this content for other procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b01fefb5-361b-4296-9ac4-67bb1d561a33', 'd19e5b59-ad19-4e46-80d5-41adb9298e75', 1, 'Open and endoscopic carpal tunnel release are always coded identically regardless of approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e0a6bdd-954c-4dcb-8a65-010674b01548', 'd19e5b59-ad19-4e46-80d5-41adb9298e75', 2, 'Carpal tunnel release has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1503c34d-3158-4b30-b804-0503fded25fe', 'd19e5b59-ad19-4e46-80d5-41adb9298e75', 3, 'Carpal tunnel release coding depends solely on which wrist (left/right) is treated, not the surgical approach');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96e7c509-701c-4d69-bbc4-dc912976f598', '68da15b6-07f9-4673-a340-14b9d525f617', 0, 'Depending on the specific CPT structure, computer/robotic-assisted navigation may have its own add-on code reported in addition to the base arthroplasty code, reflecting this as an adjunctive technology used alongside (not replacing) the base procedure code, consistent with the general add-on-code concept already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce3c1e1b-40b9-4700-89e1-87c4c64ea4c5', '68da15b6-07f9-4673-a340-14b9d525f617', 1, 'Robotic-assisted TKA is always coded using an entirely separate, unrelated base procedure code from conventional TKA');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a75da2ea-54bb-49a7-ba74-0e1788c760f1', '68da15b6-07f9-4673-a340-14b9d525f617', 2, 'Navigation technology has no bearing on CPT coding for joint arthroplasty under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('646ed68c-441e-4c39-a4cb-856563e187d8', '68da15b6-07f9-4673-a340-14b9d525f617', 3, 'Robotic assistance replaces the need for the base arthroplasty procedure code entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e490637-9b04-4103-b543-b41a71e54f09', 'd08f09a8-0dcd-44bb-81d3-2af5bda3290c', 0, 'Spinal fusion codes are structured with a base code for the initial level plus add-on codes for each additional level fused, meaning the specific number of levels actually fused (as documented in the operative report) directly determines how many codes/units are reported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97c0d757-f73b-4ce7-b489-1ed45347294b', 'd08f09a8-0dcd-44bb-81d3-2af5bda3290c', 1, 'A single universal spinal fusion code applies regardless of how many vertebral levels are fused');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0409155-ae56-44ed-a9cd-e1f4b789994c', 'd08f09a8-0dcd-44bb-81d3-2af5bda3290c', 2, 'Only the highest single vertebral level fused is ever coded, with additional levels disregarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b36df096-b84c-44b1-b8c6-82aecc048840', 'd08f09a8-0dcd-44bb-81d3-2af5bda3290c', 3, 'Spinal fusion level count is relevant only to ICD-10-PCS coding, never CPT coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2bf0467-590e-4a2a-b155-2ee964846403', '813a825b-623f-497a-a3ad-ce9db7daa538', 0, 'This structure means the total number of discrete units/sites/levels actually documented as treated is frequently a direct, required input to correct code/unit selection — a coder must count and verify against the operative documentation rather than assuming a single base code covers an unlimited or unspecified number of sites');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08833377-4aff-41fe-b17c-69c22a2dc8fa', '813a825b-623f-497a-a3ad-ce9db7daa538', 1, 'Add-on codes are optional stylistic additions with no real bearing on accurate reporting of multi-site/multi-level procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('600b91dc-1ac4-47af-9961-20df5caf8843', '813a825b-623f-497a-a3ad-ce9db7daa538', 2, 'The base code alone always fully captures reimbursement for any number of additional sites/levels treated, making add-on codes redundant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2d85db5-2db1-4b5d-8893-c45265adaf83', '813a825b-623f-497a-a3ad-ce9db7daa538', 3, 'This structure applies only to spinal procedures, with no broader relevance to other multi-site procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37fadf3d-b268-4842-a7b3-2c6e413f6ddc', '9d99dac9-4ae6-4ed7-a2fb-a5fc565d1426', 0, 'Venography (venous system imaging) and arteriography (arterial system imaging) have distinct code families reflecting the different vascular system being studied, despite both being catheter-based/contrast-based vascular imaging techniques');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdb6c95e-2923-4ebd-bc8f-5ebe7e81ae0d', '9d99dac9-4ae6-4ed7-a2fb-a5fc565d1426', 1, 'Venography and arteriography are coded identically since both are vascular imaging studies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e205aed-52f7-42e5-bf0c-a016e905408d', '9d99dac9-4ae6-4ed7-a2fb-a5fc565d1426', 2, 'Venography has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9b243bf-d85c-4680-8e7c-d6e0ae7bdcdb', '9d99dac9-4ae6-4ed7-a2fb-a5fc565d1426', 3, 'The vascular system studied (venous vs. arterial) has no bearing on code selection, only the body region does');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f594bcf5-ffbb-4def-aa4e-03ff887af389', 'fdaf24aa-96f4-4ad7-a98c-3c1cfe8e625c', 0, 'IVC filter placement has its own specific code reflecting this distinct interventional radiology procedure, generally reported in addition to any applicable imaging guidance code per that guidance code''s own bundling rules');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b21ce82-516e-497d-9ece-fa54a2a099d5', 'fdaf24aa-96f4-4ad7-a98c-3c1cfe8e625c', 1, 'IVC filter placement is coded identically to a routine venogram');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f799de22-5385-4de4-a468-fc226ebe8dbd', 'fdaf24aa-96f4-4ad7-a98c-3c1cfe8e625c', 2, 'IVC filter placement has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('732617db-de19-4114-a9c6-9ea7ab148840', 'fdaf24aa-96f4-4ad7-a98c-3c1cfe8e625c', 3, 'IVC filter placement is coded using the same code as an AV fistula creation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
