INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fafe0ab7-ac62-476c-ba88-d47b93589cde', 'aaf0b467-db85-4211-b3e1-88d201d6d4fe', 0, 'Percutaneous nephrostomy has its own specific code reflecting this distinct interventional radiology procedure, structurally similar in concept to other percutaneous drainage/access procedures already discussed (e.g., chest tube, paracentesis) but specific to the renal collecting system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5afb600-f926-4867-b28c-65b9d0d13c6b', 'aaf0b467-db85-4211-b3e1-88d201d6d4fe', 1, 'Nephrostomy tube placement is coded identically to a ureteral stent placement performed via cystoscopy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26c48bee-59cb-4731-883d-843cfcecc5a5', 'aaf0b467-db85-4211-b3e1-88d201d6d4fe', 2, 'Percutaneous nephrostomy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af43deed-5531-48cc-a1d0-dd4f61c0e539', 'aaf0b467-db85-4211-b3e1-88d201d6d4fe', 3, 'Nephrostomy tube placement is coded using the same code as a routine renal ultrasound');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
