INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c04ca831-e584-47f6-a828-21a154d8b474', 'd6a81f1a-4898-4030-ba6d-1a9894179f71', 0, 'PTC with drainage catheter placement has its own specific code(s) reflecting this distinct percutaneous hepatobiliary access procedure, structurally distinct from ERCP (an endoscopic, not percutaneous, approach to the biliary system already discussed in Paper 1)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c8eec0c-451a-45d2-9ece-ebf090bc82fb', 'd6a81f1a-4898-4030-ba6d-1a9894179f71', 1, 'PTC is coded identically to ERCP since both address biliary obstruction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('979d311c-eee1-441b-84b9-c5fadbcd7e26', 'd6a81f1a-4898-4030-ba6d-1a9894179f71', 2, 'Percutaneous biliary drainage has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ddb04675-d870-4360-96d3-73776ce53ec3', 'd6a81f1a-4898-4030-ba6d-1a9894179f71', 3, 'PTC is coded using the same code as a routine abdominal ultrasound');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
