INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b3bd01e-1552-4195-afcb-73eac6c8c573', '2da87623-1a53-4cac-86de-61bb995fda36', 0, 'UFE has its own specific code reflecting this distinct embolization procedure, generally reported with appropriate catheterization/imaging codes as structured by that specific procedure''s own code descriptor requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e352febd-4940-4938-84d2-43dbc43cb748', '2da87623-1a53-4cac-86de-61bb995fda36', 1, 'UFE is coded identically to a diagnostic pelvic ultrasound');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6a7bc83-1d3f-4bb1-a2e0-be1ce2b565da', '2da87623-1a53-4cac-86de-61bb995fda36', 2, 'UFE has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31938efb-0abb-47f2-8635-cb0c20d73582', '2da87623-1a53-4cac-86de-61bb995fda36', 3, 'UFE is coded using the same code as a hysterectomy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7c5a338-6037-49ee-8da0-9894a7e4b34a', 'e804a7e2-63e7-4549-be2b-f2849a2183b7', 0, 'A chest X-ray performed for this confirmatory purpose is generally coded using the standard applicable chest X-ray code (e.g., based on number of views), since the code is based on the study actually performed, not automatically bundled into or excluded from billing simply because its purpose was device-placement confirmation rather than a symptom-driven diagnostic indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7cda7a29-ccfc-4cbb-9946-a9588b25c0b5', 'e804a7e2-63e7-4549-be2b-f2849a2183b7', 1, 'Confirmatory chest X-rays for line placement can never be separately coded under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c87621a-c06d-4bb6-aeb3-99278f273c1e', 'e804a7e2-63e7-4549-be2b-f2849a2183b7', 2, 'This scenario requires an entirely different, unique code specific to ''line placement confirmation'' distinct from standard chest X-ray codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff834911-1279-42f3-9f88-77023360f24c', 'e804a7e2-63e7-4549-be2b-f2849a2183b7', 3, 'Confirmatory imaging is always bundled into the central line placement code with no separate reporting ever possible, regardless of who performs/interprets it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef3304f2-e6d6-4b93-93ac-b71bc8e25691', '29c0174f-3e41-4c00-8953-e1b3388912b0', 0, 'CTA (CT imaging specifically protocoled and timed to evaluate vascular structures, typically with contrast) has its own specific code(s) distinct from a routine CT scan of the same anatomic area, reflecting the different imaging protocol/clinical purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0b0213a-7c09-4ddc-8b79-7f34cc8aa0e9', '29c0174f-3e41-4c00-8953-e1b3388912b0', 1, 'CTA and routine CT are coded identically since both use CT technology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('638da6d0-0de9-4b6b-a97f-c9ae6ed44233', '29c0174f-3e41-4c00-8953-e1b3388912b0', 2, 'CTA has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f58b2df-2a20-4fea-ad24-4df289ffee49', '29c0174f-3e41-4c00-8953-e1b3388912b0', 3, 'CTA coding depends solely on the contrast volume used, not the imaging protocol/purpose');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd346343-d14c-446c-a444-2786aa4cea15', '1017a6ed-7734-43d1-b383-0c782756ac52', 0, 'MRA (MRI specifically protocoled to evaluate vascular structures) has its own specific code(s) distinct from a routine MRI of the same anatomic area, mirroring the same protocol-specific coding distinction already established for CTA versus routine CT');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4bcc0a4f-49de-4841-af14-80e8bdc618e6', '1017a6ed-7734-43d1-b383-0c782756ac52', 1, 'MRA and routine MRI are coded identically since both use MRI technology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdc2248b-7156-45e1-b900-a7cf22b58b69', '1017a6ed-7734-43d1-b383-0c782756ac52', 2, 'MRA has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d36092d-964c-4f09-b856-fcc32751f04d', '1017a6ed-7734-43d1-b383-0c782756ac52', 3, 'MRA is coded using the same code as a nuclear medicine study');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('90bd017c-93e3-4393-bd73-155ecfaafaaf', '68f96092-72f2-4a2b-a425-7cce6e4e50ff', 0, 'The imaging order/report should specify the actual protocol used (e.g., specific angiographic timing/contrast bolus technique for CTA/MRA), since this documented protocol detail — not just the general body area imaged — is what determines correct code selection between the routine and angiographic code options');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb924e36-2b62-41e9-b524-96747b345829', '68f96092-72f2-4a2b-a425-7cce6e4e50ff', 1, 'No specific protocol documentation is needed since routine and angiographic studies of the same body area are coded identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16fb2ef9-f447-4d74-ba1e-ed4e96ebb5d6', '68f96092-72f2-4a2b-a425-7cce6e4e50ff', 2, 'Only the ordering physician''s stated reason for the study (not the actual protocol performed) determines whether CTA or routine CT coding applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('766012b6-9992-45f4-9f18-87a3908a2abf', '68f96092-72f2-4a2b-a425-7cce6e4e50ff', 3, 'Protocol documentation is relevant only for MRI studies, never CT studies');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48376b29-41f9-49f9-b39b-35afc56eca33', '6b7c8c73-b178-40fd-9e22-14884a914568', 0, 'Assume all interventional radiology procedures are billed using a single generic ''interventional radiology'' code regardless of the specific vessel, organ system, or technique involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('340b84f9-a315-4e1e-b128-5ef2ad14361a', '6b7c8c73-b178-40fd-9e22-14884a914568', 1, 'Identify the specific vascular system/organ target (arterial vs. venous vs. biliary vs. renal), the specific technique/device used, and whether diagnostic and therapeutic/guidance components represent bundled or separately reportable work per that specific code''s descriptor — the same disciplined, descriptor-matching approach already established throughout this content''s Radiology and Surgery sections');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('933abc4a-73c7-4327-8f27-cde7ac5bd769', '6b7c8c73-b178-40fd-9e22-14884a914568', 2, 'Interventional radiology procedures require no image-guidance consideration since guidance is always separately billed regardless of code structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c61c7100-83f6-4744-bb6a-d0dbb35b0720', '6b7c8c73-b178-40fd-9e22-14884a914568', 3, 'Rely on the referring physician''s order alone without confirming what was actually performed and documented by the interventional radiologist');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2eb616a-bd86-47cd-9e81-1904be0d0791', '11a6c310-702e-44d5-8b8b-97999b286d6a', 0, 'CMP and BMP are distinct, separately defined panel codes with different specific component-test lists, meaning the physician''s actual order (and the tests actually performed) — not just the clinical reason for testing — determines which specific panel code applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07f3c0c0-c689-4b6a-88fb-66ec8f4099b9', '11a6c310-702e-44d5-8b8b-97999b286d6a', 1, 'CMP and BMP are coded identically regardless of which specific components were actually tested');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('572ae822-fe63-4dd9-a8f7-3e6d44a55dc9', '11a6c310-702e-44d5-8b8b-97999b286d6a', 2, 'Only CMP has a CPT code; BMP has no corresponding code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56170dec-c9f5-4a45-98e6-001bfd22ad6b', '11a6c310-702e-44d5-8b8b-97999b286d6a', 3, 'Panel selection depends solely on the clinical indication, never on which specific component tests were actually performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('beefa6d6-8530-4748-b4a0-ed111a5c786c', '67093e38-1050-489e-95f9-bed970b998f7', 0, 'Presumptive drug screening panels may be coded based on the number of drug classes/analytes tested via the specific method used, consistent with the general principle that laboratory coding reflects the actual scope of testing performed and documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3368589d-d3bc-4bfc-a589-f8929818c976', '67093e38-1050-489e-95f9-bed970b998f7', 1, 'A multi-panel drug screen is always coded using a single flat code regardless of how many drug classes are actually tested');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5784709-43c2-4e2f-a261-4debd241a5c3', '67093e38-1050-489e-95f9-bed970b998f7', 2, 'Only definitive (confirmatory) drug testing has any CPT code; presumptive multi-panel screening has none');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50a68269-b6b2-4289-afd3-eb0e9af9089f', '67093e38-1050-489e-95f9-bed970b998f7', 3, 'The number of drug classes tested has no bearing on presumptive drug screening code selection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ef982ff-935d-43e5-8dcb-0fd1b4dc6138', 'b638b977-bc9c-4b66-a887-b04798416a21', 0, 'High-volume drug testing has no distinct compliance considerations from any other laboratory service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8133343-1378-420b-b322-d965e5aaa495', 'b638b977-bc9c-4b66-a887-b04798416a21', 1, 'Given documented OIG/payer scrutiny of medically unnecessary or excessive drug testing patterns in some pain management/addiction treatment contexts, ensuring testing frequency and scope (presumptive vs. definitive, and which specific substances) is genuinely clinically driven and documented (not a routine, undifferentiated standing order for every patient regardless of individual clinical need) is a reasonable, real compliance consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60be7d9d-8d96-41e8-bdcc-113528dad677', 'b638b977-bc9c-4b66-a887-b04798416a21', 2, 'Drug testing compliance concerns apply only to illicit drug testing, never testing related to prescribed controlled substances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3432ce97-fc2a-4bb1-b278-aadc61ce4a2c', 'b638b977-bc9c-4b66-a887-b04798416a21', 3, 'Testing frequency and clinical necessity have no bearing on drug testing compliance exposure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ac6dc32-b9df-45b0-bbfc-47fae5b47085', '4bad3b03-3d46-4d6a-8e05-fba21c11027c', 0, 'Therapeutic drug monitoring has its own specific code(s) per the specific drug/analyte being measured, distinct from the drug-screening/toxicology codes discussed earlier, since the clinical PURPOSE (dose monitoring for a known prescribed medication) and testing approach differ from screening for undisclosed/illicit substance use');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c9d46b8-bffe-46f9-bcd8-d2fb2dabc7f9', '4bad3b03-3d46-4d6a-8e05-fba21c11027c', 1, 'Therapeutic drug monitoring is coded identically to a general toxicology screening panel');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52d65207-4118-428c-b3fa-332a007aec0b', '4bad3b03-3d46-4d6a-8e05-fba21c11027c', 2, 'Therapeutic drug monitoring has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9afb7eb8-abc3-45fb-8fa2-bb4f9315a8c7', '4bad3b03-3d46-4d6a-8e05-fba21c11027c', 3, 'Drug level monitoring is coded using the same code regardless of which specific drug is being measured');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd82f6f5-c2c0-4bd7-8ca0-cc8e1aec2228', 'ca58435b-4957-4e12-9185-012fd6d4552e', 0, 'Quantification of a confirmed substance''s specific concentration may be a distinct, code-relevant element beyond simple qualitative confirmation of presence, consistent with the general qualitative-versus-quantitative testing distinction already established for laboratory coding generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('360ad931-c3ba-454c-8253-372b8cfb8fd0', 'ca58435b-4957-4e12-9185-012fd6d4552e', 1, 'Quantification is never a separate coding consideration once a substance has been qualitatively confirmed present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec2ace28-77bd-42b6-8252-5c737553b025', 'ca58435b-4957-4e12-9185-012fd6d4552e', 2, 'All confirmatory drug testing is coded identically regardless of whether quantification was also performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db5149f2-d5ff-46b9-b355-24a26a484376', 'ca58435b-4957-4e12-9185-012fd6d4552e', 3, 'Quantification applies only to blood alcohol testing, never other substance classes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77fb3366-5ed5-412c-a143-1d80e1960fa4', 'dda4fa07-a1e5-4cb1-aa2e-060950a22f16', 0, 'Breath alcohol testing may have its own specific code distinct from blood/urine ethanol testing, reflecting the different specimen type/testing method used, consistent with the general specimen-type/method-specificity principle already established for laboratory coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('feced8d4-8294-4c39-b003-0f9e2ecdd6d8', 'dda4fa07-a1e5-4cb1-aa2e-060950a22f16', 1, 'Breath, blood, and urine alcohol testing are always coded identically regardless of specimen type/method');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0df915ab-13c2-48a9-98a3-69dba688639b', 'dda4fa07-a1e5-4cb1-aa2e-060950a22f16', 2, 'Breath alcohol testing has no CPT code and can never be billed in a clinical setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0af9e358-adeb-4ea4-8888-1ceeff107d3d', 'dda4fa07-a1e5-4cb1-aa2e-060950a22f16', 3, 'Alcohol testing method has no bearing on code selection, only the resulting blood alcohol concentration value does');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ce4f55e-70ae-437e-893f-3cd9c06f32c9', '3f123d6e-3895-4590-94a3-b79becfeccb2', 0, 'Documentation should reflect both the presumptive screening result AND the definitive confirmatory testing performed (and why, e.g., confirming a positive/unexpected screening result), since both may be separately, appropriately codeable when each represents genuine, medically necessary distinct testing rather than routine, undifferentiated reflex confirmation of every screen regardless of result');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ba301e9-8265-4c05-9b11-40cf2c3c6770', '3f123d6e-3895-4590-94a3-b79becfeccb2', 1, 'Only one of the two test types may ever be coded on the same date regardless of clinical circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('477df77e-78ea-4190-b6d4-e61005449d93', '3f123d6e-3895-4590-94a3-b79becfeccb2', 2, 'Definitive confirmation is always automatically included in the presumptive screening code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02e627de-3611-4942-80ee-a18c5aa820cc', '3f123d6e-3895-4590-94a3-b79becfeccb2', 3, 'No documentation is needed since presumptive and definitive testing are assumed to always occur together automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a96cbd14-3467-48a7-9b95-e9b8aa7673d0', 'a28d48cf-8b01-42b0-b6c9-e801540f6564', 0, 'This is a coincidental, unrelated terminology overlap between microbiology and toxicology with no shared underlying principle');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4781d5b5-5ca4-4a48-a9f4-3b3ae28968af', 'a28d48cf-8b01-42b0-b6c9-e801540f6564', 1, 'Both reflect the same broader laboratory-testing principle: a preliminary, less specific/lower-cost screening method (presumptive) versus a more specific, confirmatory method (definitive) — recognizing which category a specific test result represents, and coding to the actual method performed, is a recurring skill applicable across multiple laboratory subsections, not unique to either microbiology or toxicology alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1291cfb5-82de-4ff1-8729-fcaa2ca70884', 'a28d48cf-8b01-42b0-b6c9-e801540f6564', 2, 'Presumptive testing exists only in toxicology; microbiology never uses a presumptive-versus-definitive distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8697454-1822-4f99-835b-e9525dcfb193', 'a28d48cf-8b01-42b0-b6c9-e801540f6564', 3, 'Definitive testing is always required before ANY presumptive result may ever be reported or acted upon clinically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e25cb63f-7ff2-4d6e-b3d6-c320cfca4836', 'd08f19ec-44c6-4c4a-868b-f111cfd13fdb', 0, 'Specimen validity testing may have its own separately identifiable code(s), distinct from the drug screening panel itself, reflecting that this represents an additional, distinct testing component addressing specimen integrity rather than drug detection itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cef1724b-c0d4-4c22-9938-3702dad434e1', 'd08f19ec-44c6-4c4a-868b-f111cfd13fdb', 1, 'Specimen validity testing is always included in the drug screen panel code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ffa1390-14a2-4abd-8714-078c18d2bb11', 'd08f19ec-44c6-4c4a-868b-f111cfd13fdb', 2, 'Specimen validity testing has no CPT code and can never be billed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac954b53-3406-485f-9042-e016daccf3a1', 'd08f19ec-44c6-4c4a-868b-f111cfd13fdb', 3, 'Specimen validity results have no bearing on the clinical or coding validity of the accompanying drug screen result');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c207cc5e-0d49-49cb-bdc6-44560d43b946', 'bd89971c-7ba3-4620-906f-b91444c33735', 0, 'Assume all drug/toxicology testing is billed using a single generic code regardless of methodology, substance scope, or clinical purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8025bd9-79a0-45e5-8bd0-a8b035b6f561', 'bd89971c-7ba3-4620-906f-b91444c33735', 1, 'Identify the specific testing methodology (presumptive/immunoassay vs. definitive/confirmatory), the specific substances/drug classes actually tested, whether quantification was performed, and the clinical purpose (screening vs. therapeutic monitoring) — then match these specifics to the correct code, applying the same documentation-specificity discipline established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('504a11b8-3c9d-4ec8-98ab-95694684218f', 'bd89971c-7ba3-4620-906f-b91444c33735', 2, 'Toxicology coding depends solely on the ordering physician''s specialty, not the actual testing performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70e66dd8-d624-4fd6-9fc9-829ee9d7310f', 'bd89971c-7ba3-4620-906f-b91444c33735', 3, 'Rely on the laboratory''s internal test menu naming convention alone, without confirming it matches the actual CPT code descriptor''s defined scope');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('509f83ba-1508-4e25-a8b4-acd3b68f485d', '2bbd86c6-65c8-4a5e-b49f-4fd072d0eefc', 0, 'Tympanometry has its own specific code, distinct from pure-tone audiometry, since it measures a different physiologic parameter (middle ear/eardrum mobility) rather than hearing thresholds across frequencies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('977bad55-fd28-45e2-9c3e-54eb44403bba', '2bbd86c6-65c8-4a5e-b49f-4fd072d0eefc', 1, 'Tympanometry and pure-tone audiometry are coded identically since both are performed in an audiology evaluation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb83bca7-04c5-42da-b289-19c985048e75', '2bbd86c6-65c8-4a5e-b49f-4fd072d0eefc', 2, 'Tympanometry has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('019c3aa2-fead-4224-ad62-ed477c8cc351', '2bbd86c6-65c8-4a5e-b49f-4fd072d0eefc', 3, 'Tympanometry is coded using the same code as a vestibular function test');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36551393-9356-4808-a9f0-112b4054a5ef', 'a24cbe00-b0f9-4ba1-8d6a-e3b378664243', 0, 'OAE testing has its own specific code, distinct from pure-tone audiometry and tympanometry, reflecting yet another distinct physiologic measurement (cochlear outer hair cell function) within the broader audiology test family');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1140f9d3-e33d-4c52-9cf3-76f6a16328c2', 'a24cbe00-b0f9-4ba1-8d6a-e3b378664243', 1, 'OAE testing is coded identically to pure-tone audiometry since both assess hearing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3229d901-4abb-499a-8a24-43f45e825a18', 'a24cbe00-b0f9-4ba1-8d6a-e3b378664243', 2, 'OAE testing has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba1a9a77-c354-492d-af93-77ccb5732a9f', 'a24cbe00-b0f9-4ba1-8d6a-e3b378664243', 3, 'OAE testing is coded using the same code as a vestibular function test since both are objective (non-behavioral) tests');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5961fa0-0189-40ef-9d9c-76a4ff21be2d', '52564a96-9c11-4f0e-843b-a3a68501ab68', 0, 'Each distinct test type performed may be separately reportable per its own appropriate code, consistent with the general ''genuinely distinct services, each separately coded'' principle already established throughout this content for multi-component diagnostic evaluations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3577f455-0b7f-4948-ae6a-d1aac56aac0f', '52564a96-9c11-4f0e-843b-a3a68501ab68', 1, 'All three tests are always combined into a single ''newborn hearing screening'' code regardless of which specific tests were actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57ce4efc-ed64-415b-84de-5584383aab6d', '52564a96-9c11-4f0e-843b-a3a68501ab68', 2, 'Only one test type may ever be coded per encounter, regardless of how many distinct, medically necessary tests were performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3dffde8-29ff-4c7f-8c32-f07f6da2bb9c', '52564a96-9c11-4f0e-843b-a3a68501ab68', 3, 'Newborn hearing testing has no distinct CPT codes and must use unlisted procedure codes for all three test types');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bce46592-819a-4f29-a295-1bf351703e3c', 'e3e22ee1-acfe-4653-9b98-bd4c1cf7d609', 0, 'ABR (an objective, electrophysiologic test measuring brainstem response to sound, not requiring patient behavioral feedback) has its own specific code, distinct from behavioral audiometry, reflecting the fundamentally different testing methodology (objective/electrophysiologic vs. subjective/behavioral)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('513fd491-cb5a-456b-b325-9eb69a80ffbc', 'e3e22ee1-acfe-4653-9b98-bd4c1cf7d609', 1, 'ABR and behavioral audiometry are coded identically since both assess hearing function');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8212b08-64d2-4d62-83df-8d3fc8fa9add', 'e3e22ee1-acfe-4653-9b98-bd4c1cf7d609', 2, 'ABR has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5df0c834-32d3-4c86-8323-947abb48eb6f', 'e3e22ee1-acfe-4653-9b98-bd4c1cf7d609', 3, 'ABR is coded using the same code as OAE testing since both are objective tests');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e3914b3-35a1-4ba4-aa37-8da65175d903', '576e94a0-5b29-41ee-9a54-ef9345eb5f7f', 0, 'The audiologic report should specify exactly which distinct tests were actually performed (not simply ''comprehensive hearing evaluation performed''), since each represents its own separately codeable service with its own specific code requirements, consistent with the documentation-specificity theme established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf86bb6a-dff6-412f-9cc4-27815cbade66', '576e94a0-5b29-41ee-9a54-ef9345eb5f7f', 1, 'A single general statement that ''a hearing evaluation was performed'' is sufficient to support billing for any combination of the distinct test types discussed in this paper');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7403e0de-6f02-42fb-a26a-d5e02af569ce', '576e94a0-5b29-41ee-9a54-ef9345eb5f7f', 2, 'Documentation specificity is irrelevant to audiology coding since all these tests are always bundled into one comprehensive code regardless of which were actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec4e9e87-8f1c-45ba-a251-bd8846be7334', '576e94a0-5b29-41ee-9a54-ef9345eb5f7f', 3, 'Only the audiologist''s verbal summary to the patient, not written documentation, is relevant to audiology coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7d0f995-cd6e-4f2d-9ebc-421990af5631', '6f129afe-292f-4335-a9af-54fd4c9e90a2', 0, 'Hearing aid evaluation/fitting has its own specific code family, reflecting a distinct clinical service (assessing candidacy for and fitting an amplification device) from diagnostic hearing testing (measuring the extent/type of hearing loss itself)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea610cfc-e030-446b-9080-32a481685ddc', '6f129afe-292f-4335-a9af-54fd4c9e90a2', 1, 'Hearing aid fitting is coded identically to pure-tone audiometry since both relate to hearing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ebd571f-29df-42a9-a7ec-35e90ac5d563', '6f129afe-292f-4335-a9af-54fd4c9e90a2', 2, 'Hearing aid evaluation has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd6d0487-b256-412d-b08a-587cca836cf4', '6f129afe-292f-4335-a9af-54fd4c9e90a2', 3, 'Hearing aid fitting services are always bundled into the cochlear implant programming code discussed earlier in this paper');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba5b7466-92d9-47a1-8e20-7678624d8bc4', 'ff7c0a72-2036-4858-976b-70d73accdf92', 0, 'VEMP testing has its own specific code, distinct from ENG/VNG, reflecting yet another distinct vestibular test methodology (measuring a different vestibular structure''s function via muscle response to sound) within the broader vestibular testing family already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc0e79be-f4a8-4e6c-a68c-1bebd9f0943c', 'ff7c0a72-2036-4858-976b-70d73accdf92', 1, 'VEMP is coded identically to ENG/VNG since both are vestibular function tests');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e459125a-3f1a-4ca2-aaa4-c9b85c503687', 'ff7c0a72-2036-4858-976b-70d73accdf92', 2, 'VEMP has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20c04cbd-4f6b-4013-9545-8411ee6c1e79', 'ff7c0a72-2036-4858-976b-70d73accdf92', 3, 'VEMP is coded using the same code as pure-tone audiometry');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2ccc65d-105e-4998-a782-e4c38187bd77', 'e7e9113e-7c95-4db4-991e-9998aa3232b9', 0, 'Computerized dynamic posturography has its own specific code, reflecting yet another distinct balance/vestibular-adjacent assessment methodology (measuring postural control/sway under varying sensory conditions) different from ENG/VNG and VEMP');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d02fe73c-ba55-4a80-97d1-514083761305', 'e7e9113e-7c95-4db4-991e-9998aa3232b9', 1, 'Posturography is coded identically to ENG/VNG since both assess balance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2274407-4d94-4152-9e50-ffb4b9308c75', 'e7e9113e-7c95-4db4-991e-9998aa3232b9', 2, 'Posturography has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a7417d9-aa5a-4272-bb82-11175cd01c18', 'e7e9113e-7c95-4db4-991e-9998aa3232b9', 3, 'Posturography is coded using the same code as a routine neurological gait assessment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d81f52d2-2113-4a48-afc7-a2a512e71947', '6a145a1e-e8e8-45c3-b0f4-17b143ab40bf', 0, 'A single broad clinical category (e.g., ''hearing testing'' or ''balance testing'') frequently encompasses multiple genuinely distinct, separately-defined CPT codes reflecting different underlying physiologic measurements/methodologies — accurate coding requires identifying which SPECIFIC test was actually performed rather than treating the broad category as a single undifferentiated, interchangeable service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f434e226-105a-4dd2-ab57-3d7a5d6b304b', '6a145a1e-e8e8-45c3-b0f4-17b143ab40bf', 1, 'All tests within a broad clinical category like ''hearing testing'' are functionally interchangeable and may be coded using whichever specific code is most familiar to the coder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fdabdcfe-9fa4-421e-9520-07017de2c952', '6a145a1e-e8e8-45c3-b0f4-17b143ab40bf', 2, 'This pattern is unique to audiology/vestibular testing and doesn''t reflect a broader CPT coding principle applicable elsewhere');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ee0f52d-740b-4119-bf95-ef8c9991ba6e', '6a145a1e-e8e8-45c3-b0f4-17b143ab40bf', 3, 'Broad clinical categories always have exactly one corresponding CPT code, making test-type specificity irrelevant to code selection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f58892a1-ba59-4e93-84c3-5f988b596709', '4eb0b00f-fde9-4f68-8ec7-905726748749', 0, 'Assume audiology/vestibular codes are billed as a flat per-visit fee with no distinction for which specific tests were performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('488af12a-c344-4236-88ab-41abc91e6768', '4eb0b00f-fde9-4f68-8ec7-905726748749', 1, 'Apply the same underlying analytical discipline already established for the Medicine section generally (identifying the specific service structure/methodology actually documented) to audiology/vestibular testing specifically — recognizing which distinct test(s) among the several genuinely different methodologies discussed were actually performed, then matching to the correct specific code(s)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('375c890b-ab5f-43cb-a2ef-ccd412787fbb', '4eb0b00f-fde9-4f68-8ec7-905726748749', 2, 'Audiology and vestibular testing require an entirely separate analytical approach unrelated to the rest of the Medicine section''s coding principles');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15c0d5d8-0724-464d-a919-77ff7240b1fc', '4eb0b00f-fde9-4f68-8ec7-905726748749', 3, 'Rely on the referring physician''s diagnosis code alone to determine which audiology/vestibular test code applies, without confirming which specific test was actually performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75f42f57-ce9b-46e6-80cd-70af40776fa8', '71dc1660-de95-44af-aef7-016527c63cec', 0, 'An anatomic finger modifier (e.g., FA, F1-F9, depending on which specific finger), analogous to the LT/RT laterality modifiers already discussed, used to specify exactly which digit was treated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('055b1abd-41eb-47b0-8d05-20f06aeaedfe', '71dc1660-de95-44af-aef7-016527c63cec', 1, 'Modifier 50 (bilateral procedure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fba27378-2885-4ab4-86a6-d9e33d444b47', '71dc1660-de95-44af-aef7-016527c63cec', 2, 'Modifier 51 (multiple procedures)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fe5b774-f410-4032-b471-51454face726', '71dc1660-de95-44af-aef7-016527c63cec', 3, 'Modifier 22 (increased procedural services)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf371766-b91d-455b-a86e-07a49a556350', '9b763f47-5593-4dd9-90de-560a5d66d629', 0, 'Used when the operating surgeon personally administers regional or general anesthesia for their own procedure (rather than a separate anesthesia provider), appended to the surgical procedure code (not the anesthesia code) to reflect this circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f336c5b-76b2-47ca-9c3e-8dd1ca0c1e7d', '9b763f47-5593-4dd9-90de-560a5d66d629', 1, 'Used to indicate a procedure was performed by an assistant surgeon');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac1b695d-9888-457e-9f6f-d3e6a6546880', '9b763f47-5593-4dd9-90de-560a5d66d629', 2, 'Used to indicate anesthesia services were provided by a certified registered nurse anesthetist (CRNA) rather than an anesthesiologist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27cecd74-3e35-48f1-a726-1fbe7b3f53f1', '9b763f47-5593-4dd9-90de-560a5d66d629', 3, 'Used interchangeably with modifier 23 (unusual anesthesia)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0fe3a1ec-39ac-4f93-8a64-7d5e4a4474e3', '3de6abb4-a592-4516-8937-73bfaa540870', 0, 'Used when a procedure that usually requires no anesthesia or only local/topical anesthesia genuinely requires general or regional anesthesia due to unusual circumstances, appended to the anesthesia code to reflect this atypical requirement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69cf82ee-2408-4824-9960-a0ad7a61b66b', '3de6abb4-a592-4516-8937-73bfaa540870', 1, 'Used for any case involving general anesthesia, regardless of whether that procedure typically requires it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2087c00e-6ac3-4883-9cf8-ef56e5c7f0ef', '3de6abb4-a592-4516-8937-73bfaa540870', 2, 'Used to indicate a bilateral anesthesia service');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d00e3a81-13f9-4f19-a9fd-bb665fc15f82', '3de6abb4-a592-4516-8937-73bfaa540870', 3, 'Used interchangeably with modifier 47');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91e52f72-456e-4c6e-90fa-0575a34cbe25', '5ec12614-747e-4a90-972f-f4682087c22e', 0, 'Used to indicate a service was required by a third party (e.g., a court order, workers'' compensation requirement, or mandated second-opinion consultation), reflecting the circumstance under which the service was ordered rather than any change to the clinical service itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58377315-c4ce-46de-9e52-174e669a3730', '5ec12614-747e-4a90-972f-f4682087c22e', 1, 'Used to indicate a procedure was reduced in scope');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d19b0f6-7264-4a14-b735-8b5fb4f8cf37', '5ec12614-747e-4a90-972f-f4682087c22e', 2, 'Used to indicate two surgeons performed the procedure together');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4fda193-2dbd-452e-b94a-f425f4d869c6', '5ec12614-747e-4a90-972f-f4682087c22e', 3, 'Used to indicate a service was provided via telehealth');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fcdb30c7-da15-4df4-86b1-b1ade760a889', 'e084ece3-397f-4107-9e70-99d150f6d482', 0, 'Used to indicate a service, though it may also be reportable under a non-preventive code, was provided according to specific evidence-based preventive service guidelines/mandates (relevant to certain insurance coverage rules, e.g., ACA preventive service provisions requiring first-dollar coverage), flagging its preventive nature for coverage-determination purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10e37677-941b-4985-8143-9f2af7259015', 'e084ece3-397f-4107-9e70-99d150f6d482', 1, 'Used to indicate a bilateral preventive procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0ad1508-9891-4928-8d49-eba4ba7f512b', 'e084ece3-397f-4107-9e70-99d150f6d482', 2, 'Used interchangeably with modifier 25');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4725b7c1-f59a-471f-8407-6bfd26c6bb6e', 'e084ece3-397f-4107-9e70-99d150f6d482', 3, 'Used only for pediatric preventive visits, never adult preventive services');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('872d20b4-de06-4b1c-9e60-b87d3a907d06', '4ed8fec2-252e-4afb-b01a-32ef0b543c16', 0, 'Each of the two co-surgeons reports the SAME procedure code with modifier 62 appended, each submitting their own separate claim for their own distinct portion of the shared primary-surgeon work, rather than one surgeon billing as primary and the other as an assistant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78f9e9a3-e27e-49ee-bcab-69d683640929', '4ed8fec2-252e-4afb-b01a-32ef0b543c16', 1, 'Only one of the two co-surgeons may ever submit a claim; the other''s work is unbillable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('728d5a82-774e-48c0-a593-4e14c462b09d', '4ed8fec2-252e-4afb-b01a-32ef0b543c16', 2, 'Each co-surgeon uses a completely different procedure code from the other, reflecting their different anatomic focus');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('275709fd-62e5-4eb0-9b80-1c5d786bd4db', '4ed8fec2-252e-4afb-b01a-32ef0b543c16', 3, 'Modifier 62 is appended only to the higher-complexity surgeon''s claim, not both');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbf9dc1c-f3b2-4a80-994f-11014fca0624', 'e128448b-45eb-4054-8975-cc0b40c69dec', 0, 'Used when a highly complex procedure requires the concurrent services of several physicians (often of different specialties) plus other highly skilled/specially trained personnel, all functioning as an integrated surgical team, reported by each participating physician on their claim for that procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54d669b0-ef42-4bb9-abc9-204f5a5fc437', 'e128448b-45eb-4054-8975-cc0b40c69dec', 1, 'Used interchangeably with modifier 62 (two surgeons) for any case involving more than one physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16658e7f-0489-4b10-85b3-50c83c52983d', 'e128448b-45eb-4054-8975-cc0b40c69dec', 2, 'Used only for organ transplant procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a87e4a7d-829a-4d4b-b4a7-64b4e568f942', 'e128448b-45eb-4054-8975-cc0b40c69dec', 3, 'Used to indicate an assistant surgeon was present');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c92e523a-1814-4ad1-9693-d93c85ae1104', '14493075-7f7d-4f8b-ba2c-f576db55d7db', 0, 'The specific ROLE each physician played (co-primary surgeon on a shared procedure, part of a larger integrated team, or an assisting-but-not-co-primary role) determines which modifier applies — these are not interchangeable options for ''more than one physician was involved,'' but reflect genuinely different physician-role structures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('478dd9eb-f84e-48be-a7de-1d9d8b8cbd39', '14493075-7f7d-4f8b-ba2c-f576db55d7db', 1, 'Any case with more than one physician automatically uses modifier 62 regardless of the actual roles involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81add063-38fb-43ef-98c7-a1015d4c0ce3', '14493075-7f7d-4f8b-ba2c-f576db55d7db', 2, 'The number of physicians alone (two vs. three or more) is the only factor determining which of these modifiers applies, regardless of their actual roles');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4469647f-4af3-4ade-8ce9-f2d7579edaba', '14493075-7f7d-4f8b-ba2c-f576db55d7db', 3, 'These modifiers are functionally identical and may be used interchangeably based on coder preference');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('901a5922-70b6-48e4-856c-8836deb53caf', '0ad6dfa7-878a-480c-b8ff-fd661c9a9a00', 0, 'Used to indicate that more than the number of modifiers a claim form/system can otherwise accommodate are being applied to a single procedure code, signaling that additional modifier information is documented elsewhere on the claim (e.g., in a narrative field) — a claims-mechanics modifier rather than one describing a clinical circumstance itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8feea30-4a83-447e-82db-3a95b107250d', '0ad6dfa7-878a-480c-b8ff-fd661c9a9a00', 1, 'Used to indicate a procedure was performed 99 times');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b13f0db4-61c6-4a2b-9cb0-516b91b2cf46', '0ad6dfa7-878a-480c-b8ff-fd661c9a9a00', 2, 'Used interchangeably with modifier 22 (increased procedural services)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d470e1d0-d646-45d6-a6a0-0a3ee76e0563', '0ad6dfa7-878a-480c-b8ff-fd661c9a9a00', 3, 'Used only when no other modifiers apply to a claim line');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb500087-a193-495b-97f5-57fea39e5685', '0654e643-0541-49e5-88d4-71bfa5ec591c', 0, 'Modifiers exist on a spectrum of purposes — clinical distinctness (59/X{EPSU}), procedural circumstance (22, 52, 53, 78, 79, 58, 24, 25), physician role (62, 66, 80/81/82, 47), anatomic specificity (50, LT/RT, finger/toe modifiers), delivery modality (95), and payer/coverage signaling (32, 33, GA/GX/GY/GZ) — and accurate selection requires first identifying WHICH of these distinct purposes the actual documented circumstance reflects, then selecting the specific modifier within that category that precisely matches the documented facts');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6ef1b91-bce5-4aa9-bfbb-a1008a721797', '0654e643-0541-49e5-88d4-71bfa5ec591c', 1, 'All modifiers serve the same basic function (indicating something unusual happened) and may be selected somewhat interchangeably as long as one plausible modifier is applied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d26802ab-4ec1-4c6d-b452-93ce8d80e975', '0654e643-0541-49e5-88d4-71bfa5ec591c', 2, 'Only clinical-distinctness modifiers (59/X{EPSU}) have any real compliance significance; all other modifier categories are administrative formalities with no accuracy requirement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60e3d265-b822-4b42-aa4d-c642e3ada5e0', '0654e643-0541-49e5-88d4-71bfa5ec591c', 3, 'The safest approach is always applying the maximum number of modifiers to every claim line to ensure at least one is correct');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
